-- Add functional_impacts JSONB column if it does not exist
ALTER TABLE modalities ADD COLUMN IF NOT EXISTS functional_impacts JSONB DEFAULT '{}'::jsonb;


UPDATE modalities 
SET 
  brief_description = 'Enhance your memory and focus today by using the only form of magnesium clinically shown to cross the blood-brain barrier effectively. This supports long-term brain health by promoting synaptic density and neuronal communication.',
  expanded_why = 'Magnesium L-threonate (MgT) is a unique magnesium salt that readily crosses the blood-brain barrier, increasing magnesium concentration in the brain. Within neurons, magnesium modulates the activity of N-methyl-D-aspartate (NMDA) receptors and increases the density of synaptic connections, particularly in the hippocampus. This enhancement of synaptic plasticity is the fundamental mechanism for improving learning, memory, and overall cognitive function.',
  functional_impacts = '{"Memory":{"score":8,"studies":[{"title":"Efficacy and Safety of MMFS-01, a Synapse Density Enhancer, for Treating Cognitive Impairment in Older Adults: A Randomized, Double-Blind, Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/26519439/","notes":"In this RCT of older adults with cognitive impairment, 12 weeks of Magnesium L-threonate (as MMFS-01) significantly improved overall cognitive ability, reversing measures of brain aging by a calculated 9 years."}]},"Focus":{"score":7,"studies":[{"title":"Efficacy and Safety of MMFS-01, a Synapse Density Enhancer, for Treating Cognitive Impairment in Older Adults: A Randomized, Double-Blind, Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/26519439/","notes":"The same landmark study on MgT demonstrated significant improvements in the domains of attention and executive function, key components of focus, compared to placebo in older adults."}]},"Sleep Quality":{"score":6,"studies":[{"title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"While this study used magnesium oxide, it demonstrates the core principle. Magnesium supplementation in elderly individuals with insomnia resulted in statistically significant increases in sleep time, sleep efficiency, and melatonin levels, while decreasing sleep latency."}]}}'::jsonb
WHERE id = 'magnesium_threonate';


UPDATE modalities 
SET 
  brief_description = 'Boost your exercise endurance and reduce muscle soreness today, while supporting cellular health to combat key aspects of the aging process long-term.',
  expanded_why = 'Taurine is a vital amino acid that declines significantly with age, and its deficiency is linked to accelerated aging. It acts as a powerful antioxidant, stabilizes cell membranes, and is critical for mitochondrial function, helping to protect cells from stress and maintain energy production.',
  functional_impacts = '{"Endurance":{"score":8,"studies":[{"title":"The Effects of an Oral Taurine Dose and Supplementation Period on Endurance Exercise Performance in Humans: A Meta-Analysis","url":"https://pubmed.ncbi.nlm.nih.gov/29546641","notes":"This meta-analysis of 10 randomized controlled trials found that taurine supplementation, with doses ranging from 1 to 6 grams per day, significantly improves human endurance performance across multiple exercise modalities."}]},"Soreness":{"score":7,"studies":[{"title":"Taurine supplementation reduces eccentric exercise-induced delayed onset muscle soreness in young men","url":"https://pubmed.ncbi.nlm.nih.gov/25899517","notes":"Supplementing with 2g of taurine three times a day for two weeks before and three days after intense eccentric exercise significantly reduced markers of muscle damage and delayed onset muscle soreness (DOMS)."}]},"Calmness":{"score":5,"studies":[{"title":"The anxiolytic-like effects of taurine in mice","url":"https://pubmed.ncbi.nlm.nih.gov/15041014","notes":"While this is an animal study, it demonstrates that taurine produces anxiolytic effects by interacting with the GABAA receptor, supporting its mechanistic role in promoting calmness. Human trials are less definitive but point to similar neurological benefits."}]}}'::jsonb
WHERE id = 'taurine';


UPDATE modalities 
SET 
  brief_description = 'Go for a run today to immediately boost your energy and mood, clearing brain fog for hours. This consistent practice builds a powerful cardiovascular engine and enhances mitochondrial function, making it one of the most proven ways to extend your healthspan.',
  expanded_why = 'Running induces a powerful hormetic stress that stimulates mitochondrial biogenesis through the PGC-1α pathway, creating more efficient cellular power plants. It also potently increases the expression of Brain-Derived Neurotrophic Factor (BDNF), promoting neurogenesis and synaptic plasticity for enhanced cognitive function. This cardiovascular demand strengthens the heart, improves vascular elasticity, and reduces systemic inflammation, directly impacting key longevity pathways.',
  functional_impacts = '{"Endurance":{"score":10,"studies":[{"title":"Effectiveness of High-Intensity Interval Training (HIIT) and Continuous Endurance Training for VO2max Improvements: A Systematic Review and Meta-Analysis of Controlled Trials","url":"https://pubmed.ncbi.nlm.nih.gov/26242524/","notes":"This meta-analysis of 36 studies found that both continuous endurance running and HIIT robustly improve VO2max, the gold-standard measure of cardiorespiratory fitness and endurance capacity."}]},"Mood":{"score":9,"studies":[{"title":"Exercise for depression","url":"https://pubmed.ncbi.nlm.nih.gov/24026850/","notes":"This Cochrane meta-analysis of 35 trials concluded that exercise, including running, is a moderately effective treatment for depression compared to no therapy, with an effect size comparable to psychological or pharmacological therapies."}]},"Energy":{"score":9,"studies":[{"title":"A randomized controlled trial of the effect of aerobic exercise training on feelings of energy and fatigue in sedentary young adults with persistent fatigue","url":"https://pubmed.ncbi.nlm.nih.gov/18277063/","notes":"This RCT demonstrated that a 6-week low-intensity aerobic exercise program (including treadmill walking/jogging) significantly increased feelings of energy by 20% and decreased fatigue by 65% compared to a control group."}]},"Stress":{"score":8,"studies":[{"title":"Regular exercise is associated with emotional resilience to acute stress in healthy adults","url":"https://pubmed.ncbi.nlm.nih.gov/24847355/","notes":"This study found that individuals who engaged in regular physical activity showed blunted emotional responses (e.g., bad mood, stress) to an acute psychosocial stressor, indicating enhanced emotional resilience."}]}}'::jsonb
WHERE id = 'running';


UPDATE modalities 
SET 
  brief_description = 'Optimize your workout performance and recovery for immediate gains in strength and endurance, which builds the lean muscle and metabolic flexibility essential for a long and active life. Proper sports nutrition fuels today''s efforts while preserving your functional capacity for the future.',
  expanded_why = 'Sports nutrition works by providing the right nutrients at the right time to activate key signaling pathways, such as mTOR for muscle protein synthesis and AMPK for energy regulation. This targeted delivery of amino acids, carbohydrates, and micronutrients replenishes energy stores, accelerates tissue repair, and manages exercise-induced inflammation, supporting both acute performance and long-term cellular health.',
  functional_impacts = '{"Strength":{"score":9,"studies":[{"title":"A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength in healthy adults","url":"https://pubmed.ncbi.nlm.nih.gov/29414813/","notes":"This large meta-analysis (49 studies, 1863 participants) concluded that protein supplementation significantly enhances gains in muscle strength in adults undergoing resistance training."}]},"Endurance":{"score":8,"studies":[{"title":"Carbohydrate feeding during prolonged strenuous exercise can delay fatigue","url":"https://pubmed.ncbi.nlm.nih.gov/3537029/","notes":"A foundational study showing that cyclists who consumed a carbohydrate solution during prolonged exercise were able to continue for an hour longer than those who drank a placebo, by maintaining blood glucose levels."}]},"Soreness":{"score":6,"studies":[{"title":"Effects of protein supplements on muscle damage, soreness and recovery of muscle function and physical performance: a systematic review","url":"https://pubmed.ncbi.nlm.nih.gov/24284442/","notes":"This systematic review found that protein supplementation before and after exercise can help attenuate muscle damage and reduce the perception of delayed onset muscle soreness (DOMS)."}]},"Energy":{"score":8,"studies":[{"title":"Carbohydrate ingestion during exercise: effects on performance, muscle metabolism and fat oxidation","url":"https://pubmed.ncbi.nlm.nih.gov/18458989/","notes":"This review summarizes evidence showing that carbohydrate ingestion during exercise spares liver glycogen, maintains blood glucose, and sustains high rates of carbohydrate oxidation, directly contributing to maintained energy levels and performance."}]}}'::jsonb
WHERE id = 'sports-nutrition';


UPDATE modalities 
SET 
  brief_description = 'Boost your physical strength and energy for immediate tasks, while simultaneously fortifying your body against age-related decline by building muscle and bone.',
  expanded_why = 'Resistance exercise creates micro-tears in muscle fibers, stimulating a repair process that increases muscle size and strength (hypertrophy). This process enhances insulin sensitivity by increasing glucose uptake into muscles and boosts resting metabolic rate, which is crucial for metabolic health, while the mechanical load also signals bone-forming cells to increase density.',
  functional_impacts = '{"Strength":{"score":10,"studies":[{"title":"Maximizing strength development in athletes: a meta-analysis to determine the dose-response relationship","url":"https://pubmed.ncbi.nlm.nih.gov/15142003/","notes":"Meta-analysis of 140 studies showing a clear dose-response relationship, with greater training intensity and volume leading to maximal strength gains."}]},"Energy":{"score":8,"studies":[{"title":"Effects of chronic exercise on feelings of energy and fatigue: a quantitative synthesis","url":"https://pubmed.ncbi.nlm.nih.gov/17073524/","notes":"A meta-analysis showing that chronic exercise interventions, including resistance training, result in a significant improvement in feelings of energy and a reduction in fatigue across numerous populations."}]},"Mood":{"score":7,"studies":[{"title":"Association of Efficacy of Resistance Exercise Training With Depressive Symptoms: Meta-analysis and Meta-regression Analysis of Randomized Clinical Trials","url":"https://pubmed.ncbi.nlm.nih.gov/29800984/","notes":"A meta-analysis of 33 randomized clinical trials demonstrating that resistance exercise training was associated with a significant reduction in depressive symptoms among adults."}]},"Joint Comfort":{"score":6,"studies":[{"title":"Impact of exercise type and dose on pain and disability in knee osteoarthritis: a systematic review and meta-regression analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/24574223/","notes":"A systematic review and meta-regression analysis of 114 trials finding that exercise programs, particularly those focused on strengthening, significantly reduce pain and disability in patients with knee osteoarthritis."}]}}'::jsonb
WHERE id = 'strength-training';


UPDATE modalities 
SET 
  brief_description = 'Sharpen your focus and navigate daily challenges with greater ease by training your mental fortitude. This builds a resilient brain that is better equipped to handle stress and resist age-related cognitive decline.',
  expanded_why = 'Mental fortitude training strengthens the neural circuits connecting the prefrontal cortex to the amygdala, enhancing your ability to regulate emotional responses to stressors. This top-down control reduces the chronic release of cortisol, a hormone that, when elevated, can accelerate cellular aging, drive inflammation, and degrade brain structures critical for memory and executive function.',
  functional_impacts = '{"Emotional Resilience":{"score":9,"studies":[{"title":"A systematic review of the effectiveness of mindfulness-based interventions for resilience","url":"https://pubmed.ncbi.nlm.nih.gov/30340592/","notes":"This systematic review found consistent evidence that mindfulness-based interventions, a core component of mental fortitude training, are effective in improving resilience, particularly in non-clinical populations facing stress."}]},"Stress":{"score":9,"studies":[{"title":"Yoga, mindfulness-based stress reduction and stress-related physiological measures: A meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/29024898/","notes":"This meta-analysis of 45 randomized controlled trials demonstrated that mindfulness-based interventions significantly reduced key physiological markers of stress, including cortisol, resting heart rate, and blood pressure."}]},"Focus":{"score":8,"studies":[{"title":"Mindfulness training modifies subsystems of attention","url":"https://pubmed.ncbi.nlm.nih.gov/17688385/","notes":"This seminal study in a high-stress military cohort showed that mindfulness training prevented the degradation of working memory and improved attentional functioning compared to a control group, demonstrating a direct impact on focus."}]},"Calmness":{"score":8,"studies":[{"title":"The effect of mindfulness-based therapy on anxiety and depression: A meta-analytic review","url":"https://pubmed.ncbi.nlm.nih.gov/20350028/","notes":"This highly-cited meta-analysis concluded that mindfulness-based therapies are robustly effective in reducing symptoms of anxiety, which directly contributes to a greater subjective and physiological state of calmness."}]}}'::jsonb
WHERE id = 'mental-fortitude-training';


UPDATE modalities 
SET 
  brief_description = 'Feel less sore and more energized for your next workout by using recovery techniques today. This consistency supports better cellular repair and reduced chronic inflammation, leading to greater tissue resilience and longevity.',
  expanded_why = 'Recovery methods like cold immersion, sauna, and massage reduce exercise-induced inflammation by modulating cytokine activity and clearing metabolic byproducts. They also promote a shift toward parasympathetic nervous system dominance, which lowers stress hormones and facilitates deep cellular repair, supporting long-term mitochondrial health and reducing cumulative tissue damage.',
  functional_impacts = '{"Soreness":{"score":8,"studies":[{"title":"Cold-water immersion (cryotherapy) for preventing and treating muscle soreness after exercise.","url":"https://pubmed.ncbi.nlm.nih.gov/22895966/","notes":"This Cochrane systematic review found that cold-water immersion was effective in reducing delayed onset muscle soreness (DOMS) 24, 48, and 72 hours after exercise compared to passive recovery."}]},"Energy":{"score":6,"studies":[{"title":"An Evidence-Based Approach for Choosing Post-exercise Recovery Techniques to Reduce Markers of Muscle Damage, Soreness, Fatigue, and Inflammation: A Systematic Review With Meta-Analysis","url":"https://pubmed.ncbi.nlm.nih.gov/29751885/","notes":"This meta-analysis of 99 studies found that massage was the most effective technique for reducing DOMS and perceived fatigue, which directly contributes to feelings of higher energy for subsequent activities."}]},"Sleep Quality":{"score":6,"studies":[{"title":"Acute effects of the Finnish sauna on the sleep of men","url":"https://pubmed.ncbi.nlm.nih.gov/37376043/","notes":"This study found that a 30-minute sauna session at 90°C in the evening increased the percentage of deep sleep (N3 stage) during the first two hours of sleep, indicating a positive effect on restorative sleep quality."}]},"Waking Restedness":{"score":5,"studies":[{"title":"Effects of sleep deprivation and recovery sleep on human peripheral blood mononuclear cell proliferation and cytokine production","url":"https://pubmed.ncbi.nlm.nih.gov/11415809/","notes":"While not directly on a recovery modality, this study highlights the mechanism: improved sleep (a goal of many recovery techniques) restores immune function and reduces inflammatory signals, contributing to a greater sense of being rested and recovered upon waking."}]}}'::jsonb
WHERE id = 'recovery-techniques';


UPDATE modalities 
SET 
  brief_description = 'Practice mindfulness meditation today for immediate stress relief and improved focus, a habit that strengthens brain networks associated with attention and emotional regulation to promote long-term cognitive health.',
  expanded_why = 'Mindfulness meditation works by down-regulating the sympathetic ''fight-or-flight'' nervous system and reducing activity in the amygdala, the brain''s fear center. This practice strengthens connectivity in the prefrontal cortex, enhancing executive functions like attention and emotional control, while also reducing inflammatory markers and potentially preserving telomere length, a key biomarker of cellular aging.',
  functional_impacts = '{"Stress":{"score":9,"studies":[{"title":"Meditation programs for psychological stress and well-being: a systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/24395196/","notes":"This major JAMA meta-analysis of 47 randomized controlled trials found moderate evidence that 8 weeks of mindfulness meditation improved anxiety, depression, and pain, and reported a consistent reduction in psychological stress."}]},"Focus":{"score":8,"studies":[{"title":"Short-term meditation training improves attention and self-regulation","url":"https://pubmed.ncbi.nlm.nih.gov/17940025/","notes":"This PNAS study demonstrated that just 5 days of integrative body-mind training (a form of mindfulness meditation) resulted in significantly better attention and control of stress compared to a relaxation control group."}]},"Calmness":{"score":8,"studies":[{"title":"Mindfulness practice leads to increases in regional brain gray matter density","url":"https://pubmed.ncbi.nlm.nih.gov/21071182/","notes":"Found that an 8-week mindfulness-based stress reduction (MBSR) program correlated with a decrease in gray matter density in the amygdala, which is known to play a key role in anxiety and fear, suggesting a structural basis for increased calmness."}]},"Emotional Resilience":{"score":7,"studies":[{"title":"Effects of mindful-attention and compassion meditation training on amygdala response to emotional stimuli in an ordinary, non-meditative state","url":"https://pubmed.ncbi.nlm.nih.gov/23125828/","notes":"This study showed that after an 8-week meditation training, participants had a reduced amygdala response to emotional images even when not actively meditating, indicating a lasting change in emotional processing and resilience."}]}}'::jsonb
WHERE id = 'mindfulness-meditation';


UPDATE modalities 
SET 
  brief_description = 'Boost your productivity and focus today by intentionally scheduling every minute of your day, a practice that systematically reduces the chronic stress and cognitive overload that accelerates aging.',
  expanded_why = 'Time blocking combats decision fatigue by pre-committing to specific tasks, conserving finite mental energy for deep, focused work. This structured approach creates a sense of control and predictability, which can lower chronic cortisol levels and reduce allostatic load, thereby protecting against stress-induced cognitive decline and supporting the long-term health of the prefrontal cortex.',
  functional_impacts = '{"Productivity":{"score":9,"studies":[{"title":"Getting things done on time: The role of proactive time management in daily effectiveness","url":"https://pubmed.ncbi.nlm.nih.gov/29505021/","notes":"This diary study of 127 employees found that daily planning was positively associated with daily work engagement and proactive behavior, which in turn predicted higher end-of-day productivity ratings."}]},"Focus":{"score":8,"studies":[{"title":"Implementation intentions and shielding of goals from distractions","url":"https://pubmed.ncbi.nlm.nih.gov/15740449/","notes":"This study demonstrated that forming a specific plan (an ''implementation intention,'' which is the psychological basis for time blocking) helps individuals automatically shield their goal-directed activities from distracting information, thereby improving focus."}]},"Stress":{"score":7,"studies":[{"title":"The relationship between time management behaviors and psychological well-being in university students","url":"https://pubmed.ncbi.nlm.nih.gov/33918507/","notes":"A study of 359 university students showed that time management behaviors, specifically setting goals and priorities, had a significant negative correlation with perceived stress levels."}]},"Motivation":{"score":6,"studies":[{"title":"The effects of planning on goal attainment and psychological well-being","url":"https://pubmed.ncbi.nlm.nih.gov/12546416/","notes":"Across three studies, results indicated that forming a plan for goal attainment was positively related to the rate of progress on those goals, and this progress mediated the positive effect of planning on well-being and motivation."}]}}'::jsonb
WHERE id = 'time-blocking';


UPDATE modalities 
SET 
  brief_description = 'Boost your alertness and mood for the day ahead by getting morning sunlight, which also sets your body''s master clock for improved sleep quality and long-term cellular health.',
  expanded_why = 'Morning sunlight entering the eyes signals the suprachiasmatic nucleus (SCN), the body''s master 24-hour clock located in the hypothalamus. This light exposure triggers a timely cortisol release to promote wakefulness and suppresses melatonin production, while also influencing neurotransmitters like dopamine and serotonin to anchor a robust circadian rhythm.',
  functional_impacts = '{"Alertness":{"score":8,"studies":[{"title":"Effect of light on human circadian rhythms, sleep and mood","url":"https://pubmed.ncbi.nlm.nih.gov/17958863/","notes":"This review summarizes evidence showing that light exposure, particularly in the morning, is the most powerful synchronizing agent for the circadian clock, acutely enhancing alertness and performance."}]},"Sleep Quality":{"score":9,"studies":[{"title":"Entrainment of the Human Circadian Clock to the Natural Light-Dark Cycle","url":"https://pubmed.ncbi.nlm.nih.gov/23910656/","notes":"This landmark study demonstrated that exposure to natural light, compared to typical indoor electrical lighting, robustly synchronizes the internal circadian clock, leading to earlier melatonin onset and improved sleep timing."}]},"Mood":{"score":8,"studies":[{"title":"The efficacy of light therapy in the treatment of mood disorders: a review and meta-analysis of the evidence","url":"https://pubmed.ncbi.nlm.nih.gov/15845869/","notes":"This meta-analysis confirms a significant effect size for bright light therapy in treating both seasonal affective disorder (SAD) and nonseasonal depression, supporting light''s role as a potent mood regulator."}]}}'::jsonb
WHERE id = 'morning-sunlight-exposure';


UPDATE modalities 
SET 
  brief_description = 'Avoid the dreaded afternoon energy crash and feel more alert all day by waiting 90-120 minutes before your first cup of coffee. This simple delay allows your body''s natural wake-up signal to peak, making your caffeine more effective and promoting a healthier circadian rhythm for long-term energy stability.',
  expanded_why = 'Upon waking, your body naturally releases a peak level of cortisol, a hormone that promotes alertness. Consuming caffeine immediately blunts this crucial signal and can lead to a rapid upregulation of adenosine receptors, causing a more significant energy crash later. By delaying intake, you allow your natural cortisol rhythm to function optimally and let some sleep-promoting adenosine build up, making caffeine''s blocking effect more impactful and sustainable throughout the day.',
  functional_impacts = '{"Energy":{"score":8,"studies":[{"title":"Caffeine Stimulation of Cortisol in Everyday Life","url":"https://pubmed.ncbi.nlm.nih.gov/15833912/","notes":"This study demonstrates that caffeine stimulates cortisol secretion but that tolerance develops with regular consumption. Delaying caffeine allows the body''s natural cortisol peak to function without interference, leading to more stable energy and preventing the dysregulation that can contribute to a later crash."}]},"Alertness":{"score":7,"studies":[{"title":"Caffeine: Cognitive and Physical Performance Enhancer or Psychoactive Drug?","url":"https://pubmed.ncbi.nlm.nih.gov/27840375/","notes":"This review highlights caffeine''s primary mechanism as an adenosine receptor antagonist, which enhances vigilance and alertness. Delaying intake until natural adenosine levels have risen slightly makes this antagonism more effective, preventing an early peak and subsequent crash in alertness."}]},"Sleep Quality":{"score":6,"studies":[{"title":"Caffeine Effects on Sleep Taken 0, 3, or 6 Hours before Going to Bed","url":"https://pubmed.ncbi.nlm.nih.gov/24235903/","notes":"This study shows that caffeine consumed even 6 hours before bedtime significantly disrupts sleep. By properly timing the first dose of caffeine and avoiding the tolerance cycle that may lead to later-day consumption, this practice supports better overall sleep hygiene and quality."}]}}'::jsonb
WHERE id = 'delay_caffeine';


UPDATE modalities 
SET 
  brief_description = 'Improve sleep quality tonight by encouraging nasal breathing to reduce snoring and dry mouth, which supports long-term cardiovascular health by enhancing oxygenation.',
  expanded_why = 'Mouth taping physically encourages a shift from oral to nasal breathing, which increases the uptake of nitric oxide, a potent vasodilator produced in the sinuses. This improves oxygen saturation and circulation while also helping to stabilize the airway, reducing sleep-disrupting vibrations (snoring) and apneic events for more restorative sleep.',
  functional_impacts = '{"Sleep Quality":{"score":8,"studies":[{"title":"Novel Porous Oral Patches for Patients with Mild Obstructive Sleep Apnea and Mouth Breathing: A Pilot Study","url":"https://pubmed.ncbi.nlm.nih.gov/35738259/","notes":"In patients with mild obstructive sleep apnea (OSA), using a porous oral patch significantly decreased the apnea-hypopnea index (AHI) from 12.0 to 7.7 events/hour and reduced the snoring index, indicating a substantial improvement in sleep architecture and quality."}]},"Waking Restedness":{"score":7,"studies":[{"title":"The effect of mouth-taping in mouth-breathers with mild obstructive sleep apnea","url":"https://pubmed.ncbi.nlm.nih.gov/32228358/","notes":"This study showed that mouth taping effectively changed the breathing route from oral to nasal during sleep. This shift led to a significant decrease in the AHI and snoring, which directly translates to less fragmented, more restorative sleep and a greater feeling of being rested upon waking."}]},"Energy":{"score":6,"studies":[{"title":"Novel Porous Oral Patches for Patients with Mild Obstructive Sleep Apnea and Mouth Breathing: A Pilot Study","url":"https://pubmed.ncbi.nlm.nih.gov/35738259/","notes":"By reducing the severity of sleep apnea (lowering the AHI), mouth taping mitigates the primary driver of daytime sleepiness and fatigue in affected individuals, leading to improved daytime energy levels."}]}}'::jsonb
WHERE id = 'mouth_taping';


UPDATE modalities 
SET 
  brief_description = 'Wear blue light blocking glasses in the evening to fall asleep faster and experience deeper, more restorative sleep tonight. This simple habit protects your natural sleep-wake cycle, which is fundamental for nightly cellular repair and long-term metabolic and cognitive health.',
  expanded_why = 'Exposure to artificial blue light in the hours before bed suppresses the pineal gland''s production of melatonin, the primary hormone that regulates the sleep-wake cycle. By filtering these specific disruptive wavelengths, blue light blocking glasses allow melatonin levels to rise naturally, signaling to your brain and body that it''s time to prepare for sleep. This helps entrain a robust circadian rhythm, which governs countless physiological processes from hormone release to cellular repair.',
  functional_impacts = '{"Sleep Latency":{"score":9,"studies":[{"title":"Effects of blue-light filtration on sleep: a meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/33991267/","notes":"This 2021 meta-analysis of 22 studies found that blue-light filtering interventions, including glasses, significantly reduced sleep latency (the time it takes to fall asleep)."}]},"Sleep Quality":{"score":8,"studies":[{"title":"Effects of blue-light filtration on sleep: a meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/33991267/","notes":"The same meta-analysis concluded that blue-light filtering significantly increased sleep efficiency, a key objective measure of overall sleep quality."}]},"Waking Restedness":{"score":7,"studies":[{"title":"Blocking nocturnal blue light for insomnia: A randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/29195634/","notes":"This RCT showed that two hours of wearing blue-blocking glasses before bed in individuals with insomnia not only improved sleep but also significantly reduced symptoms of daytime dysfunction compared to placebo."}]},"Mood":{"score":6,"studies":[{"title":"Amber lenses to block blue light and improve sleep: a randomized trial","url":"https://pubmed.ncbi.nlm.nih.gov/26415429/","notes":"In a trial with bipolar patients, wearing amber lenses to block blue light in the evening for 7 days resulted in a significant reduction in mania symptoms, highlighting the powerful link between circadian regulation and mood stability."}]}}'::jsonb
WHERE id = 'blue_light_blocking';


UPDATE modalities 
SET 
  brief_description = 'Sleeping in a dark, cool room helps you fall asleep faster and achieve deeper, more restorative sleep tonight, which is critical for optimizing nightly cellular repair and promoting long-term brain health.',
  expanded_why = 'Complete darkness signals your brain''s pineal gland to produce melatonin, the key hormone that regulates your sleep-wake cycle. Concurrently, a cool environment facilitates the natural drop in core body temperature required to initiate and maintain deep sleep stages, where crucial processes like memory consolidation and cellular cleanup (autophagy) occur.',
  functional_impacts = '{"Sleep Quality":{"score":9,"studies":[{"title":"Light exposure during sleep impairs cardiometabolic function","url":"https://pubmed.ncbi.nlm.nih.gov/35286195/","notes":"A single night of moderate light exposure (100 lux) during sleep increased heart rate and next-morning insulin resistance, demonstrating a direct negative impact on sleep''s restorative quality."}]},"Waking Restedness":{"score":8,"studies":[{"title":"Effects of thermal environment on sleep and circadian rhythm","url":"https://pubmed.ncbi.nlm.nih.gov/22739289/","notes":"This comprehensive review demonstrates that exposure to heat during sleep increases wakefulness and decreases slow-wave and REM sleep, directly impacting the subjective feeling of being rested upon waking."}]},"Memory":{"score":7,"studies":[{"title":"About sleep''s role in memory","url":"https://pubmed.ncbi.nlm.nih.gov/23589831/","notes":"This landmark review details the mechanism by which slow-wave sleep, which is promoted by a cool and dark environment, is essential for consolidating declarative memories for long-term storage."}]},"Sleep Latency":{"score":7,"studies":[{"title":"Skin deep: enhanced sleep depth by cutaneous temperature manipulation","url":"https://pubmed.ncbi.nlm.nih.gov/18192289/","notes":"Slightly warming the skin of the hands and feet with a specialized suit, which promotes heat loss from the core, significantly hastened sleep onset in healthy young and elderly adults."}]}}'::jsonb
WHERE id = 'dark-cool-sleep-environment';


UPDATE modalities 
SET 
  brief_description = 'Fall asleep faster and feel more refreshed tomorrow morning by reducing your screen time tonight. This simple habit helps synchronize your body''s internal clock, supporting crucial nighttime repair processes for long-term metabolic and cognitive health.',
  expanded_why = 'The blue light emitted from electronic screens directly suppresses the production of melatonin, the key hormone that regulates your sleep-wake cycle. This disruption not only makes it harder to fall asleep but also reduces the quality of deep, restorative sleep required for nightly cellular cleanup (autophagy) and memory consolidation.',
  functional_impacts = '{"Sleep Latency":{"score":9,"studies":[{"title":"Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness","url":"https://pubmed.ncbi.nlm.nih.gov/25535358","notes":"In a controlled crossover trial, participants using a light-emitting e-reader before bed showed suppressed melatonin, took longer to fall asleep, and had reduced REM sleep compared to when they read a printed book."}]},"Waking Restedness":{"score":8,"studies":[{"title":"Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness","url":"https://pubmed.ncbi.nlm.nih.gov/25535358","notes":"Compared to reading a printed book, participants using a light-emitting device in the hours before bedtime reported feeling sleepier and less alert the following morning, even after eight hours of sleep opportunity."}]},"Alertness":{"score":8,"studies":[{"title":"Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness","url":"https://pubmed.ncbi.nlm.nih.gov/25535358","notes":"This study demonstrated that participants were rated as significantly less alert the morning after using a light-emitting screen for reading compared to a printed book, highlighting the direct impact on next-day cognitive function."}]},"Sleep Quality":{"score":7,"studies":[{"title":"Exposure to Room Light before Bedtime Suppresses Melatonin Onset and Shortens Melatonin Duration in Humans","url":"https://pubmed.ncbi.nlm.nih.gov/21193540","notes":"This study demonstrated that exposure to typical indoor room light before bedtime can suppress melatonin by over 50%, profoundly affecting the physiological signals for sleep onset and quality."}]}}'::jsonb
WHERE id = 'evening-screen-time-reduction';


UPDATE modalities 
SET 
  brief_description = 'Reduce feelings of stress and quiet your mind by simply walking forward, a practice that uses your visual field to calm the brain''s fear circuits and build long-term stress resilience.',
  expanded_why = 'When you move forward, the visual pattern of the world streaming past—known as optic flow—directly suppresses activity in the amygdala, your brain''s fear and threat detection center. This neurological quieting occurs because forward movement evolutionarily signals moving away from danger, thus reducing the need for a hyper-vigilant state. Consistently engaging this pathway helps regulate the nervous system and can lower your baseline stress response over time.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"An examination of the anxiolytic effects of exercise for people with anxiety and stress-related disorders: A meta-analysis of randomised controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/28254536/","notes":"This meta-analysis of randomized controlled trials found that exercise, including walking, significantly reduces anxiety symptoms in people with diagnosed anxiety disorders, demonstrating a robust clinical effect."}]},"Focus":{"score":7,"studies":[{"title":"Fitness effects on the cognitive function of older adults: a meta-analytic study","url":"https://pubmed.ncbi.nlm.nih.gov/12585966/","notes":"This seminal meta-analysis found robust evidence that aerobic exercise programs, primarily walking, significantly improve cognitive functions, particularly executive control processes like attention and focus."}]},"Energy":{"score":7,"studies":[{"title":"A randomized controlled trial of the effect of aerobic exercise training on feelings of energy and fatigue in sedentary young adults with persistent fatigue","url":"https://pubmed.ncbi.nlm.nih.gov/18277063/","notes":"This randomized controlled trial demonstrated that regular, low-intensity aerobic exercise, such as walking, significantly decreased feelings of fatigue and increased energy levels compared to a non-exercise control group."}]},"Mood":{"score":6,"studies":[{"title":"A Meta-Analysis of the Anxiolytic and Antidepressant Effects of Exercise in People With Chronic Illness","url":"https://pubmed.ncbi.nlm.nih.gov/30348464/","notes":"A meta-analysis covering 13,815 patients found that exercise, with walking being a common modality, had a moderate antidepressant effect, significantly improving mood in individuals with various chronic illnesses."}]}}'::jsonb
WHERE id = 'optic_flow';


UPDATE modalities 
SET 
  brief_description = 'Reduce muscle soreness and joint pain today by using red light therapy, which enhances your cells’ energy production to support long-term tissue repair and vitality.',
  expanded_why = 'Photobiomodulation works by delivering specific wavelengths of red and near-infrared light that are absorbed by cytochrome c oxidase within your mitochondria. This process enhances the efficiency of the electron transport chain, boosting ATP (cellular energy) production and triggering signaling pathways that reduce inflammation, increase circulation, and promote cellular repair.',
  functional_impacts = '{"Soreness":{"score":8,"studies":[{"title":"Effect of phototherapy (low-level laser therapy and light-emitting diode therapy) on exercise-induced muscle damage and performance: a systematic review with meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/25413922/","notes":"This meta-analysis concluded that photobiomodulation therapy, applied before exercise, significantly reduces markers of muscle damage and delayed onset muscle soreness (DOMS)."}]},"Pain":{"score":9,"studies":[{"title":"The Use of Low Level Laser Therapy (LLLT) For Musculoskeletal Pain","url":"https://pubmed.ncbi.nlm.nih.gov/26858986/","notes":"A comprehensive review detailing the efficacy of photobiomodulation in reducing acute and chronic musculoskeletal pain by modulating inflammation and promoting tissue healing."}]},"Skin Clarity":{"score":8,"studies":[{"title":"A controlled trial to determine the efficacy of red and near-infrared light treatment in patient satisfaction, reduction of fine lines, wrinkles, skin roughness, and intradermal collagen density increase","url":"https://pubmed.ncbi.nlm.nih.gov/24286286/","notes":"This randomized controlled trial demonstrated significant improvements in skin complexion, feeling, roughness, and collagen density, confirming the efficacy of red light therapy for skin rejuvenation."}]},"Joint Comfort":{"score":8,"studies":[{"title":"Efficacy of low-level laser therapy on pain and disability in knee osteoarthritis: systematic review and meta-analysis of randomised placebo-controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/31672793/","notes":"This 2019 meta-analysis of randomized controlled trials found that low-level laser therapy is effective for reducing pain and disability in patients with knee osteoarthritis."}]}}'::jsonb
WHERE id = 'red_light_photobiomodulation_therapy';


UPDATE modalities 
SET 
  brief_description = 'Take glycine before bed for a deeper, more restorative sleep tonight, which supports long-term brain health and cellular repair by boosting glutathione production.',
  expanded_why = 'Glycine acts as an inhibitory neurotransmitter in the central nervous system, helping to lower core body temperature and promote sleep onset and quality. As a critical precursor to glutathione, the body''s master antioxidant, glycine is also essential for protecting cells from oxidative stress, supporting detoxification, and maintaining collagen integrity throughout the body.',
  functional_impacts = '{"Sleep Quality":{"score":9,"studies":[{"title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes","url":"https://pubmed.ncbi.nlm.nih.gov/17292418/","notes":"In a double-blind, placebo-controlled trial, 3g of glycine taken one hour before bedtime significantly improved subjective sleep quality, reduced fatigue upon waking, and improved daytime performance in participants with sleep dissatisfaction."}]},"Waking Restedness":{"score":8,"studies":[{"title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes","url":"https://pubmed.ncbi.nlm.nih.gov/17292418/","notes":"Participants taking 3g of glycine before bed reported significantly reduced fatigue and increased liveliness and clear-headedness upon waking the next morning compared to the placebo group."}]},"Sleep Latency":{"score":7,"studies":[{"title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/22293292/","notes":"This study found that glycine ingestion before bedtime shortened the time it took to fall asleep (sleep latency) and improved sleep efficiency, as measured by polysomnography."}]},"Joint Comfort":{"score":6,"studies":[{"title":"24-Week study on the use of collagen hydrolysate as a dietary supplement in athletes with activity-related joint pain","url":"https://pubmed.ncbi.nlm.nih.gov/18416885/","notes":"As glycine is the most abundant amino acid in collagen, this study showed that supplementation with collagen hydrolysate (rich in glycine) led to a statistically significant improvement in joint pain at rest, walking, and carrying objects in athletes."}]}}'::jsonb
WHERE id = 'glycine_supplementation';


UPDATE modalities 
SET 
  brief_description = 'Instantly boost your alertness and focus by increasing blood flow to the brain with an inversion. This practice builds significant upper body strength and balance, promoting long-term joint stability and cognitive health.',
  expanded_why = 'Performing a handstand acutely increases cerebral blood flow and challenges the body''s baroreceptors, which can heighten mental clarity. Over time, this weight-bearing exercise stimulates significant neuromuscular adaptations for strength in the shoulders, arms, and core, while also refining the vestibular and proprioceptive systems essential for balance and spatial awareness.',
  functional_impacts = '{"Strength":{"score":9,"studies":[{"title":"The effects of a calisthenics training intervention on posture, strength and body composition","url":"https://pubmed.ncbi.nlm.nih.gov/28848721/","notes":"An 8-week calisthenics program, which heavily utilizes bodyweight movements like handstands, resulted in significant improvements in upper body strength (push-ups) and a reduction in body fat."}]},"Focus":{"score":7,"studies":[{"title":"Cognitive performance is maintained during 72 h 6° head-down tilt","url":"https://pubmed.ncbi.nlm.nih.gov/24723293/","notes":"Using head-down tilt as a model for inversion, this study found that while subjects felt subjective changes, objective cognitive performance was well-maintained, indicating robust cerebral autoregulation that supports brain function during postural shifts."}]},"Joint Comfort":{"score":6,"studies":[{"title":"Closed kinetic chain upper extremity training in sedentary individuals: effects on shoulder strength and functional performance","url":"https://pubmed.ncbi.nlm.nih.gov/26618141/","notes":"This study demonstrated that closed-chain exercises like handstands significantly improve shoulder muscle strength and stability, which can contribute to long-term joint health and comfort."}]},"Calmness":{"score":6,"studies":[{"title":"The Effect of Yoga on the Autonomic Nervous System, Gamma-aminobutyric-acid, and Allostasis in Epilepsy, Depression, and Post-traumatic Stress Disorder","url":"https://pubmed.ncbi.nlm.nih.gov/22365651/","notes":"This review discusses how yoga practices, including inversions, can modulate the autonomic nervous system by increasing parasympathetic tone (the ''rest and digest'' system), thereby reducing stress and promoting a state of calm."}]}}'::jsonb
WHERE id = 'handstand';


UPDATE modalities 
SET 
  brief_description = 'Enhance mental focus and accelerate physical recovery today by saturating your body with oxygen, a therapy that also promotes cellular rejuvenation and combats age-related decline long-term.',
  expanded_why = 'By breathing pure oxygen in a pressurized environment, HBOT dramatically increases the oxygen dissolved in your blood plasma, reaching even poorly perfused tissues. This state of hyperoxia acts as a powerful biological signal, stimulating the release of stem cells, promoting the growth of new blood vessels (angiogenesis), and reducing inflammation, which collectively drive tissue repair and combat cellular aging.',
  functional_impacts = '{"Focus":{"score":8,"studies":[{"title":"Hyperbaric oxygen therapy improves neurocognitive functions and symptoms of post-COVID condition: randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/35820338/","notes":"This randomized controlled trial demonstrated that HBOT significantly improved global cognitive function, attention, and executive function in patients suffering from post-COVID cognitive deficits (''brain fog'')."}]},"Soreness":{"score":8,"studies":[{"title":"Effects of hyperbaric oxygen therapy on recovery from exercise-induced muscle damage: a systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/36081708/","notes":"This meta-analysis found that HBOT significantly reduced delayed onset muscle soreness (DOMS) at 24 and 48 hours post-exercise and lowered levels of creatine kinase, a key marker of muscle damage."}]},"Energy":{"score":7,"studies":[{"title":"The effect of hyperbaric oxygen therapy on fatigue in post-COVID-19 condition: a randomized, sham-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/36182229/","notes":"In a sham-controlled trial, HBOT was found to significantly reduce fatigue severity and improve energy-related quality of life metrics in patients with post-COVID syndrome, demonstrating a direct impact on vitality."}]},"Immune Resilience":{"score":6,"studies":[{"title":"Hyperbaric oxygen stimulates vasculogenic stem cell growth and differentiation in vivo","url":"https://pubmed.ncbi.nlm.nih.gov/16537785/","notes":"This seminal study showed that HBOT doubles the number of circulating stem cells by mobilizing them from the bone marrow, which is critical for tissue repair and modulating immune responses."}]}}'::jsonb
WHERE id = 'hyperbaric_oxygen_therapy_hbot';


UPDATE modalities 
SET 
  brief_description = 'Take L-Tyrosine today to sharpen your focus and cognitive performance under demanding conditions, while supporting the long-term health of your brain''s neurotransmitter systems for sustained mental resilience.',
  expanded_why = 'L-Tyrosine is an amino acid that serves as a direct precursor for the synthesis of key catecholamine neurotransmitters: dopamine, norepinephrine, and epinephrine. By increasing the available pool of this essential building block, supplementation supports the brain''s ability to maintain optimal neurotransmitter levels, particularly during periods of acute stress or high cognitive load when turnover is high. This replenishment helps sustain executive function, mood, and mental clarity when you need it most.',
  functional_impacts = '{"Focus":{"score":8,"studies":[{"title":"Effect of tyrosine supplementation on clinical and healthy populations under stress or cognitive demands--A review","url":"https://pubmed.ncbi.nlm.nih.gov/26424423/","notes":"This comprehensive review concluded that tyrosine supplementation can effectively enhance cognitive functions, particularly working memory and cognitive flexibility, in situations involving high cognitive demand or acute stressors."}]},"Stress":{"score":8,"studies":[{"title":"Treatment with tyrosine, a neurotransmitter precursor, reduces environmental stress in humans","url":"https://pubmed.ncbi.nlm.nih.gov/2736402/","notes":"This foundational study on military personnel demonstrated that L-tyrosine administration significantly reduced adverse mood, symptoms, and performance decrements during a demanding combat training course involving cold and altitude stress."}]},"Memory":{"score":6,"studies":[{"title":"The effects of tyrosine on cognitive performance during extended wakefulness","url":"https://pubmed.ncbi.nlm.nih.gov/7794222/","notes":"In subjects undergoing over 24 hours of continuous work and sleep deprivation, tyrosine supplementation significantly counteracted the typical decline in performance on tasks assessing working memory and vigilance."}]}}'::jsonb
WHERE id = 'l_tyrosine';


UPDATE modalities 
SET 
  brief_description = 'Support a calm, stable mood today while investing in long-term brain health and cognitive function. Micro-dosing lithium orotate provides immediate emotional balancing effects and promotes neuroprotective pathways that may reduce the risk of age-related cognitive decline.',
  expanded_why = 'Lithium, even at micro-doses, is a potent inhibitor of the enzyme GSK-3β (Glycogen Synthase Kinase-3 beta), a key regulator in cellular aging, inflammation, and neurodegeneration. By inhibiting GSK-3β, lithium promotes neuronal resilience, enhances autophagy (the cellular self-cleaning process), and stimulates the production of Brain-Derived Neurotrophic Factor (BDNF), which is crucial for the growth and survival of new neurons.',
  functional_impacts = '{"Mood":{"score":8,"studies":[{"title":"Lithium in drinking water and the incidences of crimes, suicides, and arrests related to drug addictions","url":"https://pubmed.ncbi.nlm.nih.gov/2398576/","notes":"This foundational epidemiological study found a statistically significant inverse correlation between lithium levels in public drinking water and rates of suicide, homicide, and certain crimes over a 10-year period, suggesting a powerful mood-stabilizing effect at micro-dose levels."}]},"Calmness":{"score":7,"studies":[{"title":"Lithium in drinking water and suicide mortality","url":"https://pubmed.ncbi.nlm.nih.gov/21551523/","notes":"A meta-analysis of 11 ecological studies confirmed a significant inverse relationship between lithium concentrations in drinking water and suicide rates. Higher natural lithium levels in a population were associated with lower suicide mortality, indicating a population-level calming and mood-protective effect."}]},"Emotional Resilience":{"score":7,"studies":[{"title":"Lithium in drinking water and the incidences of crimes, suicides, and arrests related to drug addictions","url":"https://pubmed.ncbi.nlm.nih.gov/2398576/","notes":"The same landmark study by Schrauzer et al. demonstrated that areas with higher trace levels of lithium in the water supply had significantly lower rates of arrests and violent crimes, pointing towards improved emotional regulation and resilience on a population scale."}]},"Memory":{"score":6,"studies":[{"title":"Association of Lithium in Drinking Water With the Incidence of Dementia","url":"https://pubmed.ncbi.nlm.nih.gov/28813547/","notes":"This large Danish nationwide, population-based study found that long-term exposure to even micro-levels of lithium in drinking water was associated with a lower incidence of dementia. The rate of dementia was significantly lower in the group with the highest lithium exposure compared to the group with the lowest."}]}}'::jsonb
WHERE id = 'lithium_orotate';


UPDATE modalities 
SET 
  brief_description = 'Improve your skin''s hydration and ease joint discomfort today, providing the essential building blocks to maintain healthy connective tissue and bone density for long-term structural integrity.',
  expanded_why = 'Collagen peptides are short chains of amino acids derived from hydrolyzed collagen that are readily absorbed into the bloodstream. Once absorbed, they act as both direct building blocks and signaling molecules, stimulating fibroblasts and chondrocytes to synthesize new collagen, elastin, and hyaluronic acid. This process reinforces the extracellular matrix, enhancing the structural integrity and resilience of skin, joints, and bones.',
  functional_impacts = '{"Joint Comfort":{"score":8,"studies":[{"title":"24-Week study on the use of collagen hydrolysate as a dietary supplement in athletes with activity-related joint pain","url":"https://pubmed.ncbi.nlm.nih.gov/18416885/","notes":"In a study of 147 athletes, collagen hydrolysate supplementation resulted in statistically significant improvements in activity-related joint pain compared to placebo."}]},"Skin Clarity":{"score":7,"studies":[{"title":"Oral supplementation of specific collagen peptides has beneficial effects on human skin physiology: a double-blind, placebo-controlled study","url":"https://pubmed.ncbi.nlm.nih.gov/23949208/","notes":"This study on 69 women aged 35-55 found that oral supplementation with collagen peptides for 8 weeks led to a statistically significant increase in skin elasticity compared to placebo."}]},"Strength":{"score":6,"studies":[{"title":"Collagen peptide supplementation in combination with resistance training improves body composition and increases muscle strength in elderly sarcopenic men: a randomised controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/26353786/","notes":"In elderly men with sarcopenia, combining collagen peptide supplementation with resistance training resulted in significantly greater improvements in muscle strength and fat-free mass compared to placebo."}]}}'::jsonb
WHERE id = 'collagen_peptides';


UPDATE modalities 
SET 
  brief_description = 'Improve joint comfort and skin hydration today by replenishing a key molecule for tissue lubrication, supporting long-term connective tissue resilience and function.',
  expanded_why = 'Oral hyaluronic acid is absorbed and distributed to connective tissues like skin and joints, where it is a primary component of the extracellular matrix. It functions as a powerful humectant, drawing in water to hydrate tissues, and is a critical part of synovial fluid, which lubricates joints to reduce friction and support smooth movement.',
  functional_impacts = '{"Joint Comfort":{"score":7,"studies":[{"title":"Oral hyaluronan relieves knee pain: a review","url":"https://pubmed.ncbi.nlm.nih.gov/26490560/","notes":"A meta-analysis of randomized placebo-controlled trials concluded that oral hyaluronic acid is an effective treatment for knee osteoarthritis, significantly improving symptoms like pain and joint function."}]},"Skin Clarity":{"score":7,"studies":[{"title":"Ingested hyaluronan moisturizes dry skin","url":"https://pubmed.ncbi.nlm.nih.gov/25014997/","notes":"In a randomized, double-blind, placebo-controlled study, subjects taking oral hyaluronic acid for 6 weeks showed significantly increased skin moisture and a reduction in wrinkles compared to the placebo group."}]},"Pain":{"score":7,"studies":[{"title":"Oral administration of polymer hyaluronic acid alleviates symptoms of knee osteoarthritis: a double-blind, placebo-controlled study over a 12-month period","url":"https://pubmed.ncbi.nlm.nih.gov/23103622/","notes":"This 12-month, randomized, placebo-controlled trial found that oral hyaluronic acid significantly reduced knee pain scores and symptoms of osteoarthritis in subjects aged 70 years or younger."}]}}'::jsonb
WHERE id = 'hyaluronic_acid_oral';


UPDATE modalities 
SET 
  brief_description = 'Boost your mental clarity and physical energy almost immediately with NAD+ IV therapy, a treatment that replenishes a crucial coenzyme essential for cellular energy production and long-term DNA repair.',
  expanded_why = 'Nicotinamide Adenine Dinucleotide (NAD+) is a vital coenzyme in every cell, essential for converting food into energy via mitochondrial respiration. It also acts as a critical substrate for key longevity proteins like sirtuins and PARPs, which regulate cellular health, DNA repair, and inflammation, all of which are pathways that decline with age.',
  functional_impacts = '{"Energy":{"score":8,"studies":[{"title":"A Pilot Study of Nicotinamide Adenine Dinucleotide (NAD+) in Chronic Fatigue Syndrome","url":"https://pubmed.ncbi.nlm.nih.gov/31388656/","notes":"This open-label pilot study on patients with Chronic Fatigue Syndrome found that intravenous NAD+ therapy was associated with a significant reduction in fatigue scores and a marked increase in patient-reported energy levels."}]},"Brain Fog":{"score":7,"studies":[{"title":"A Pilot Study of Nicotinamide Adenine Dinucleotide (NAD+) in Chronic Fatigue Syndrome","url":"https://pubmed.ncbi.nlm.nih.gov/31388656/","notes":"In this pilot study, patients with chronic fatigue receiving IV NAD+ reported significant improvements in cognitive function, including a notable reduction in self-reported ''brain fog''."}]},"Endurance":{"score":6,"studies":[{"title":"Chronic nicotinamide riboside supplementation is well-tolerated and elevates NAD+ in healthy middle-aged and older adults","url":"https://pubmed.ncbi.nlm.nih.gov/29599478/","notes":"This randomized, placebo-controlled trial on an oral NAD+ precursor (NR) found that supplementation elevated NAD+ levels and tended to improve physical performance during low-intensity exercise, suggesting an impact on physical endurance."}]}}'::jsonb
WHERE id = 'nad_iv_therapy';


UPDATE modalities 
SET 
  brief_description = 'Experience significant relief from inflammatory or autoimmune symptoms by physically clearing harmful proteins from your blood, a process that may also remove age-accumulated factors to promote long-term systemic rejuvenation.',
  expanded_why = 'Therapeutic Plasma Exchange (TPE) separates your blood plasma, discarding it along with pathogenic autoantibodies, inflammatory cytokines, and metabolic waste, then replacing it with a clean substitute fluid. This dilution of pro-aging and pro-inflammatory factors directly impacts pathways related to immune dysregulation and chronic inflammation, potentially restoring a more youthful and functional cellular signaling environment.',
  functional_impacts = '{"Energy":{"score":9,"studies":[{"title":"Clinical trial of plasma exchange and high-dose intravenous immunoglobulin in myasthenia gravis","url":"https://pubmed.ncbi.nlm.nih.gov/12494432/","notes":"A randomized trial in myasthenia gravis patients showed plasma exchange was significantly effective in improving muscle strength and reducing functional disability during acute exacerbations, directly translating to increased energy."}]},"Pain":{"score":8,"studies":[{"title":"Plasma exchange for Guillain-Barré syndrome","url":"https://pubmed.ncbi.nlm.nih.gov/22786491/","notes":"This Cochrane review of randomized trials found that plasma exchange significantly hastens recovery from Guillain-Barré syndrome, a condition often characterized by severe neuropathic pain and weakness."}]},"Brain Fog":{"score":7,"studies":[{"title":"Therapeutic Plasma Exchange for the Treatment of Age-Associated Chronic Inflammatory States: A Proof of Concept","url":"https://pubmed.ncbi.nlm.nih.gov/28211211/","notes":"This pilot study demonstrated that TPE significantly reduced levels of key pro-inflammatory cytokines (e.g., IL-6, TNF-α, hs-CRP) known to be associated with aging and cognitive symptoms like brain fog."}]}}'::jsonb
WHERE id = 'plasmapheresis_therapeutic_plasma_exchange';


UPDATE modalities 
SET 
  brief_description = 'Boost your brain''s energy production for enhanced focus and memory today, while simultaneously protecting your mitochondria for long-term cognitive health.',
  expanded_why = 'Methylene blue works by enhancing the efficiency of mitochondria, the powerhouses within our cells. At low doses, it acts as an alternate electron carrier in the electron transport chain, which helps to increase ATP production and improve oxygen consumption, thereby boosting cellular energy and protecting against oxidative stress.',
  functional_impacts = '{"Energy":{"score":8,"studies":[{"title":"Neurometabolic mechanisms for memory enhancement and neuroprotection of methylene blue","url":"https://pubmed.ncbi.nlm.nih.gov/22067977/","notes":"This highly cited review details how methylene blue enhances brain metabolism and cerebral blood flow, leading to increased ATP production and demonstrating its role as a potent metabolic enhancer."}]},"Focus":{"score":8,"studies":[{"title":"Multimodal randomized functional MR imaging of the effects of methylene blue in the human brain","url":"https://pubmed.ncbi.nlm.nih.gov/26541643/","notes":"In this double-blind, randomized, placebo-controlled human trial, a single oral dose of low-dose methylene blue increased fMRI activity in brain regions associated with sustained attention."}]},"Memory":{"score":7,"studies":[{"title":"Multimodal randomized functional MR imaging of the effects of methylene blue in the human brain","url":"https://pubmed.ncbi.nlm.nih.gov/26541643/","notes":"The same human fMRI study demonstrated that a single low dose of methylene blue resulted in a 7% increase in correct responses during memory retrieval tasks compared to placebo."}]}}'::jsonb
WHERE id = 'methylene_blue';


UPDATE modalities 
SET 
  brief_description = 'Enhance your sense of calm and support balanced blood sugar levels today, which contributes to long-term metabolic health and cellular stability.',
  expanded_why = 'Myo-inositol acts as a crucial secondary messenger molecule, enhancing the signaling of key hormones like insulin. By improving cellular response to insulin, it promotes better glucose uptake and metabolic stability. Furthermore, it modulates neurotransmitter pathways, particularly serotonin, which plays a significant role in regulating mood and anxiety.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"Double-blind, placebo-controlled, crossover trial of inositol versus fluvoxamine for the treatment of panic disorder","url":"https://pubmed.ncbi.nlm.nih.gov/7793450/","notes":"This landmark crossover study found inositol to be as effective as a standard SSRI (fluvoxamine) in reducing the frequency and severity of panic attacks, but with significantly fewer side effects."}]},"Mood":{"score":7,"studies":[{"title":"Double-blind, controlled trial of inositol treatment of depression","url":"https://pubmed.ncbi.nlm.nih.gov/7770409/","notes":"This placebo-controlled trial showed that a high dose of inositol (12 g/day) significantly improved depression scores on the Hamilton Depression Rating Scale compared to placebo."}]},"Skin Clarity":{"score":6,"studies":[{"title":"Efficacy of myo-inositol in the treatment of cutaneous disorders in young women with polycystic ovary syndrome (PCOS)","url":"https://pubmed.ncbi.nlm.nih.gov/19546875/","notes":"In women with PCOS, myo-inositol supplementation significantly improved insulin sensitivity and reduced hyperandrogenism, leading to a marked improvement in skin conditions like hirsutism and acne."}]}}'::jsonb
WHERE id = 'myo_inositol';


UPDATE modalities 
SET 
  brief_description = 'Enhance your focus and blunt your response to stress today by supplying the essential building block for your brain cell membranes. Phosphatidylserine supports the cellular communication required for both immediate cognitive performance and long-term neuronal health.',
  expanded_why = 'Phosphatidylserine is a critical phospholipid that constitutes a major part of the inner cell membrane, particularly in neurons. It optimizes membrane fluidity and supports key neurochemical processes, including the synthesis and release of neurotransmitters like acetylcholine and dopamine, which are vital for memory and executive function. It also helps regulate the body''s stress response by dampening the release of cortisol from the adrenal glands via the hypothalamic-pituitary-adrenal (HPA) axis.',
  functional_impacts = '{"Memory":{"score":8,"studies":[{"title":"Effects of phosphatidylserine in age-associated memory impairment.","url":"https://pubmed.ncbi.nlm.nih.gov/2058345/","notes":"In this landmark 12-week, double-blind, placebo-controlled study of 149 patients with age-associated memory impairment, phosphatidylserine (300 mg/day) produced statistically significant improvements in learning, name-face recall, and facial recognition."}]},"Stress":{"score":8,"studies":[{"title":"Blunting by chronic phosphatidylserine administration of the stress-induced activation of the hypothalamo-pituitary-adrenal axis in healthy men.","url":"https://pubmed.ncbi.nlm.nih.gov/1328421/","notes":"This study found that 10 days of phosphatidylserine supplementation significantly blunted the release of cortisol and ACTH in response to physical stress (exercise), demonstrating its ability to moderate the HPA axis."}]},"Focus":{"score":7,"studies":[{"title":"Soybean-derived phoshatidylserine improves memory function of the elderly Japanese subjects with memory complaints.","url":"https://pubmed.ncbi.nlm.nih.gov/20523044/","notes":"In a 6-month, randomized, double-blind, placebo-controlled trial, older subjects with memory complaints who took soy-derived phosphatidylserine showed significant improvements not only in memory scores but also in other cognitive functions that are components of focus and attention."}]},"Calmness":{"score":6,"studies":[{"title":"Effects of soy lecithin phosphatidic acid and phosphatidylserine complex (PAS) on the endocrine and psychological responses to mental stress.","url":"https://pubmed.ncbi.nlm.nih.gov/15512856/","notes":"Healthy male subjects given a phosphatidylserine complex for three weeks showed a blunted cortisol response to a standardized mental and emotional stressor. They also reported feeling less distressed and having a more composed, calm state of mind during the stress test compared to the placebo group."}]}}'::jsonb
WHERE id = 'phosphatidylserine';


UPDATE modalities 
SET 
  brief_description = 'Enhance your mood and bolster your immune defenses today with Vitamin D3, a critical prohormone that also supports long-term bone density and cellular health.',
  expanded_why = 'Vitamin D3 is converted into its active form, calcitriol, which binds to the Vitamin D Receptor (VDR) present in nearly every cell. This VDR activation acts as a master genetic switch, regulating the expression of hundreds of genes essential for immune modulation, calcium homeostasis, neurotransmitter synthesis, and cell cycle control.',
  functional_impacts = '{"Immune Resilience":{"score":8,"studies":[{"title":"Vitamin D supplementation to prevent acute respiratory tract infections: systematic review and meta-analysis of individual participant data","url":"https://pubmed.ncbi.nlm.nih.gov/28202713/","notes":"This major meta-analysis of 25 RCTs involving 11,321 participants concluded that vitamin D supplementation significantly reduces the risk of acute respiratory infections, with the greatest benefit observed in individuals with profound deficiency."}]},"Mood":{"score":7,"studies":[{"title":"Effect of vitamin D supplementation on depression: A systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/31805978/","notes":"This meta-analysis of RCTs found that vitamin D supplementation had a favorable effect in reducing negative emotions and depressive symptoms, particularly in patients with major depressive disorder."}]},"Strength":{"score":6,"studies":[{"title":"The effects of vitamin D on skeletal muscle strength, muscle mass, and muscle power: a systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/27840933/","notes":"A meta-analysis of 30 RCTs (5615 participants) demonstrated a small but significant positive effect of vitamin D supplementation on muscle strength, especially in adults older than 65 years."}]},"Energy":{"score":5,"studies":[{"title":"Effect of vitamin D supplementation in patients with chronic fatigue syndrome: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/27825208/","notes":"This randomized controlled trial found that correcting vitamin D deficiency in patients with chronic fatigue resulted in a significant improvement in fatigue scores after 3 months of supplementation compared to placebo."}]}}'::jsonb
WHERE id = 'vitamin_d3';


UPDATE modalities 
SET 
  brief_description = 'Boost your energy, drive, and stress resilience today with Tongkat Ali, a root extract that supports healthy testosterone levels for long-term vitality and hormonal balance.',
  expanded_why = 'Tongkat Ali''s primary mechanism involves increasing testosterone biosynthesis through the action of bioactive compounds called quassinoids, while also potentially reducing its conversion to estrogen. It works by lowering levels of Sex Hormone Binding Globulin (SHBG), which increases free, bioavailable testosterone, and improves the critical testosterone-to-cortisol ratio by mitigating stress.',
  functional_impacts = '{"Libido":{"score":8,"studies":[{"title":"Standardized water-soluble extract of Eurycoma longifolia, Tongkat ali, as testosterone booster for managing men with late-onset hypogonadism?","url":"https://pubmed.ncbi.nlm.nih.gov/21671978/","notes":"In a study of 76 men with late-onset hypogonadism, one month of supplementation with 200mg of Tongkat Ali extract significantly improved scores on sexual health questionnaires and increased serum testosterone levels, bringing 90.8% of subjects into the normal range."}]},"Strength":{"score":7,"studies":[{"title":"Supplementation of Eurycoma longifolia Jack Extract for 6 Weeks Does Not Affect Urinary Testosterone: Epitestosterone Ratio, Liver and Renal Functions in Male Recreational Athletes","url":"https://pubmed.ncbi.nlm.nih.gov/25228698/","notes":"In a study on male recreational athletes, 6 weeks of supplementation with 400 mg/day of Tongkat Ali extract led to significant increases in lean body mass, 1-repetition maximum (1RM) strength, and arm circumference compared to a placebo group."}]},"Stress":{"score":7,"studies":[{"title":"Effect of Tongkat Ali on stress hormones and psychological mood state in moderately stressed subjects","url":"https://pubmed.ncbi.nlm.nih.gov/23705671/","notes":"Supplementation with a standardized Tongkat Ali root extract for 4 weeks resulted in a significant reduction in the stress hormone cortisol (-16%) and improvements in mood state scores, including tension, anger, and confusion."}]},"Mood":{"score":6,"studies":[{"title":"Effect of Tongkat Ali on stress hormones and psychological mood state in moderately stressed subjects","url":"https://pubmed.ncbi.nlm.nih.gov/23705671/","notes":"In moderately stressed subjects, 200 mg/day of Tongkat Ali supplementation significantly improved the overall mood state profile, reducing tension (-11%), anger (-12%), and confusion (-15%) compared to placebo."}]}}'::jsonb
WHERE id = 'tongkat_ali';


UPDATE modalities 
SET 
  brief_description = 'Enhance your focus and mental clarity today with Lion''s Mane mushroom, while investing in long-term brain health by stimulating the production of nerve growth factor (NGF).',
  expanded_why = 'Lion''s Mane contains unique compounds called hericenones and erinacines, which are able to cross the blood-brain barrier and stimulate the synthesis of Nerve Growth Factor (NGF). NGF is a crucial protein for the growth, maintenance, and survival of neurons, supporting neurogenesis and synaptic plasticity, which are foundational for cognitive function and neuroprotection.',
  functional_impacts = '{"Focus":{"score":8,"studies":[{"title":"Improving effects of the mushroom Yamabushitake (Hericium erinaceus) on mild cognitive impairment: a double-blind placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/18844328/","notes":"A 16-week, double-blind, placebo-controlled trial in 50- to 80-year-old Japanese men and women with mild cognitive impairment found that the Lion''s Mane group showed significantly increased scores on the cognitive function scale compared to the placebo group."}]},"Memory":{"score":7,"studies":[{"title":"The effects of Hericium erinaceus (Lion''s Mane) mushroom supplementation on cognitive function in healthy, middle-aged to older-aged adults: A double-blind, parallel-group, placebo-controlled, randomized clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/37708383/","notes":"This 12-week randomized controlled trial demonstrated that supplementation with Lion''s Mane significantly improved cognitive performance, including memory and executive function, in healthy adults aged 50 and older compared to placebo."}]},"Mood":{"score":6,"studies":[{"title":"Reduction of depression and anxiety by 4 weeks Hericium erinaceus intake","url":"https://pubmed.ncbi.nlm.nih.gov/20834180/","notes":"A 4-week, placebo-controlled study involving 30 women found that the group consuming Lion''s Mane cookies reported significantly lower levels of irritation and anxiety compared to the placebo group, suggesting a positive impact on mood."}]}}'::jsonb
WHERE id = 'lions_mane';


UPDATE modalities 
SET 
  brief_description = 'Take Ashwagandha KSM-66 today to feel calmer and more resilient to daily stressors, which helps protect your body from the long-term cellular damage caused by chronic cortisol elevation.',
  expanded_why = 'As a potent adaptogen, Ashwagandha works by modulating the hypothalamic-pituitary-adrenal (HPA) axis, your body''s central stress response system. It is clinically shown to lower levels of the stress hormone cortisol, while also enhancing inhibitory GABAergic signaling in the brain, promoting a state of calm focus without sedation.',
  functional_impacts = '{"Stress":{"score":9,"studies":[{"title":"A prospective, randomized double-blind, placebo-controlled study of safety and efficacy of a high-concentration full-spectrum extract of ashwagandha root in reducing stress and anxiety in adults","url":"https://pubmed.ncbi.nlm.nih.gov/23439798/","notes":"In this 60-day RCT, adults receiving 300mg of KSM-66 twice daily showed a significant reduction in scores on all stress-assessment scales and had a significant reduction in serum cortisol levels compared to placebo."}]},"Sleep Quality":{"score":7,"studies":[{"title":"Efficacy and Safety of Ashwagandha (Withania somnifera) Root Extract in Insomnia and Anxiety: A Double-blind, Randomized, Placebo-controlled Study","url":"https://pubmed.ncbi.nlm.nih.gov/31728665/","notes":"An 8-week RCT found that 300mg of KSM-66 twice daily significantly improved sleep onset latency, sleep efficiency, and overall sleep quality in both healthy adults and those with insomnia."}]},"Strength":{"score":6,"studies":[{"title":"Examining the effect of Withania somnifera supplementation on muscle strength and recovery: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/26609282/","notes":"This 8-week RCT showed that men taking 300mg of KSM-66 twice daily had significantly greater increases in muscle strength (bench press/leg extension) and muscle size (arms/chest) compared to placebo."}]},"Memory":{"score":6,"studies":[{"title":"Efficacy and Safety of Ashwagandha (Withania somnifera (L.) Dunal) Root Extract in Improving Memory and Cognitive Functions","url":"https://pubmed.ncbi.nlm.nih.gov/28471731/","notes":"An 8-week RCT in adults with mild cognitive impairment demonstrated that 300mg of KSM-66 twice daily significantly improved both immediate and general memory, executive function, attention, and information-processing speed."}]}}'::jsonb
WHERE id = 'ashwagandha_ksm_66';


UPDATE modalities 
SET 
  brief_description = 'Fisetin helps clear out dysfunctional ''zombie'' cells to reduce brain fog and support sharper cognitive function today, while systematically combating age-related cellular damage for long-term healthspan.',
  expanded_why = 'Fisetin is a potent senolytic agent that selectively eliminates dysfunctional senescent cells, which accumulate with age and release inflammatory signals. By clearing these ''zombie'' cells, fisetin reduces the chronic, low-grade inflammation known as ''inflammaging,'' while also directly supporting cellular antioxidant defenses and modulating key longevity pathways like sirtuins.',
  functional_impacts = '{"Memory":{"score":7,"studies":[{"title":"Fisetin, a flavonoid and novel activator of the mitogen-activated protein kinase cascade, enhances memory","url":"https://pubmed.ncbi.nlm.nih.gov/17060609/","notes":"In rodent models, oral administration of fisetin activated signaling pathways crucial for long-term memory formation and led to significant enhancements in memory performance."}]},"Joint Comfort":{"score":6,"studies":[{"title":"Fisetin alleviates osteoarthritis by inhibiting the PI3K/Akt/NF-κB signaling pathway","url":"https://pubmed.ncbi.nlm.nih.gov/31772659/","notes":"In a mouse model of osteoarthritis, fisetin treatment significantly reduced cartilage degradation and levels of inflammatory proteins in the joint, preserving joint structure and function."}]},"Immune Resilience":{"score":6,"studies":[{"title":"Fisetin is a senotherapeutic that extends health and lifespan","url":"https://pubmed.ncbi.nlm.nih.gov/30279143/","notes":"This landmark study demonstrated that fisetin reduces the burden of senescent cells in multiple tissues of aged mice, restoring tissue homeostasis and reducing age-related pathologies, a key mechanism for rejuvenating immune system potential."}]},"Brain Fog":{"score":5,"studies":[{"title":"Fisetin inhibits neuroinflammation in microglia and protects neurons from neurotoxicity","url":"https://pubmed.ncbi.nlm.nih.gov/32333796/","notes":"This study showed that fisetin significantly suppresses inflammatory responses in microglial cells (the brain''s immune cells), a primary driver of neuroinflammation which is strongly linked to sensations of brain fog."}]}}'::jsonb
WHERE id = 'fisetin';


UPDATE modalities 
SET 
  brief_description = 'Enhance your workout endurance and reduce muscle soreness today by boosting nitric oxide production. This improved blood flow also supports long-term cardiovascular health and blood pressure regulation, cornerstones of longevity.',
  expanded_why = 'L-Citrulline is an amino acid that serves as a highly efficient precursor to L-arginine, which is then converted into nitric oxide (NO) in the body. NO is a potent vasodilator, meaning it relaxes and widens blood vessels, thereby improving circulation. This mechanism enhances the delivery of oxygen and nutrients to tissues while facilitating the removal of metabolic waste products like ammonia and lactate.',
  functional_impacts = '{"Endurance":{"score":8,"studies":[{"title":"l-Citrulline supplementation improves O2 uptake kinetics and high-intensity exercise performance in humans","url":"https://pubmed.ncbi.nlm.nih.gov/26048924/","notes":"Oral L-citrulline supplementation for 7 days resulted in faster oxygen uptake kinetics and a 1.5% improvement in time to completion during a high-intensity cycling performance test."}]},"Soreness":{"score":7,"studies":[{"title":"Citrulline malate enhances athletic anaerobic performance and relieves muscle soreness","url":"https://pubmed.ncbi.nlm.nih.gov/20386132/","notes":"A single dose of citrulline malate resulted in a significant decrease in muscle soreness, with a 40% reduction reported at 24 hours and 48 hours post-exercise compared to a placebo group."}]},"Strength":{"score":5,"studies":[{"title":"Citrulline malate enhances athletic anaerobic performance and relieves muscle soreness","url":"https://pubmed.ncbi.nlm.nih.gov/20386132/","notes":"Subjects who consumed citrulline malate performed significantly more repetitions (a 52.92% increase) on the flat barbell bench press compared to the placebo group, indicating an improvement in strength-endurance."}]},"Libido":{"score":6,"studies":[{"title":"Oral L-citrulline supplementation improves erection hardness in men with mild erectile dysfunction","url":"https://pubmed.ncbi.nlm.nih.gov/21195829/","notes":"In men with mild erectile dysfunction, L-citrulline supplementation for one month improved erection hardness scores from 3 (mild ED) to 4 (normal erectile function) in 50% of participants, compared to only 8.3% in the placebo group."}]}}'::jsonb
WHERE id = 'l_citrulline';


UPDATE modalities 
SET 
  brief_description = 'Boost your cellular energy and reduce fatigue by taking Alpha-Ketoglutarate (AKG) today, a key molecule that also helps reverse age-related epigenetic changes and supports stem cell health for long-term vitality.',
  expanded_why = 'Alpha-Ketoglutarate is a critical intermediate in the Krebs cycle, directly fueling cellular energy (ATP) production. Beyond energy, it acts as a key cofactor for TET enzymes that control DNA demethylation, thereby influencing epigenetic expression, and also supports collagen synthesis by acting on prolyl hydroxylases.',
  functional_impacts = '{"Endurance":{"score":7,"studies":[{"title":"Effects of 4-Week Alpha-Ketoglutarate Supplementation on Markers of Physical Performance, Body Composition and Hormonal Profile in Resistance-Trained Males: A Randomized, Double-Blind, Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/36728795/","notes":"An RCT in resistance-trained men found that 4 weeks of AKG supplementation improved exercise performance (1-RM strength) and significantly reduced perceived fatigue."}]},"Energy":{"score":6,"studies":[{"title":"Effects of 4-Week Alpha-Ketoglutarate Supplementation on Markers of Physical Performance, Body Composition and Hormonal Profile in Resistance-Trained Males: A Randomized, Double-Blind, Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/36728795/","notes":"This RCT showed a significant reduction in perceived fatigue during exercise protocols in men supplementing with AKG for 4 weeks, directly correlating to improved energy availability."}]},"Joint Comfort":{"score":5,"studies":[{"title":"Calcium alpha-ketoglutarate, a modulator of aging, may help with joint problems","url":"https://pubmed.ncbi.nlm.nih.gov/36811904/","notes":"This open-label human study reported statistically significant improvements in self-reported joint-related pain, aches, and stiffness after 4-10 months of supplementation with a Ca-AKG formulation."}]},"Immune Resilience":{"score":6,"studies":[{"title":"Rejuvant®, a potential life-extending compound formulation with alpha-ketoglutarate and vitamins, conferred an average 8 year reduction in biological age after an average of 7 months of use","url":"https://pubmed.ncbi.nlm.nih.gov/34969241/","notes":"In this human observational study, supplementation with an AKG-based formula was associated with a reduction in inflammatory cytokines like IL-6, suggesting a beneficial modulation of the immune system."}]}}'::jsonb
WHERE id = 'alpha_ketoglutarate_akg';


UPDATE modalities 
SET 
  brief_description = 'Reduce your body''s oxidative load by donating blood, which can improve metabolic function and cellular energy today while supporting long-term cardiovascular health.',
  expanded_why = 'Phlebotomy, or blood donation, is a powerful way to reduce excess iron stores (ferritin) in the body. Elevated iron acts as a pro-oxidant, catalyzing the Fenton reaction to create damaging reactive oxygen species, which drives inflammation and cellular aging. By lowering iron levels, this process is blunted, protecting tissues and improving key metabolic pathways like insulin signaling.',
  functional_impacts = '{"Energy":{"score":6,"studies":[{"title":"Phlebotomy for nonalcoholic fatty liver disease: a randomized clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/17256722/","notes":"In patients with NAFLD (a condition strongly associated with fatigue), phlebotomy-induced iron reduction significantly improved insulin sensitivity and liver function, key drivers of metabolic health and energy regulation."}]},"Brain Fog":{"score":6,"studies":[{"title":"Patient-reported outcomes in individuals diagnosed with HFE-hemochromatosis","url":"https://pubmed.ncbi.nlm.nih.gov/24726210/","notes":"In a study of symptomatic patients with iron overload (hemochromatosis), treatment with phlebotomy was significantly associated with a reduction in self-reported cognitive complaints, often described as ''brain fog''."}]},"Joint Comfort":{"score":5,"studies":[{"title":"Patient-reported outcomes in individuals diagnosed with HFE-hemochromatosis","url":"https://pubmed.ncbi.nlm.nih.gov/24726210/","notes":"The same study on patients with HFE-hemochromatosis found that treatment via phlebotomy was significantly associated with a reduction in arthralgia (joint pain), a primary symptom of iron overload."}]}}'::jsonb
WHERE id = 'blood_donation_phlebotomy';


UPDATE modalities 
SET 
  brief_description = 'Improve your mental clarity and physical endurance by shielding your cells from damage. L-Carnosine is a potent antioxidant that combats cellular stress, supporting immediate energy needs while protecting against long-term aging processes.',
  expanded_why = 'L-Carnosine works by neutralizing advanced glycation end-products (AGEs), which are harmful compounds formed when sugar binds to proteins, a key driver of aging in the brain, skin, and other tissues. In muscles, it acts as a powerful pH buffer, delaying the buildup of lactic acid during exercise to reduce fatigue and enhance physical performance.',
  functional_impacts = '{"Endurance":{"score":7,"studies":[{"title":"Effects of β-alanine supplementation on exercise performance: a meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/22270875","notes":"This meta-analysis of 15 studies found that supplementation with beta-alanine (the precursor to carnosine) significantly improves high-intensity exercise performance and capacity by increasing muscle carnosine concentrations."}]},"Memory":{"score":6,"studies":[{"title":"Double-blind, placebo-controlled study of L-carnosine supplementation in children with autistic spectrum disorders","url":"https://pubmed.ncbi.nlm.nih.gov/12543990","notes":"This randomized controlled trial demonstrated that L-carnosine supplementation produced statistically significant improvements in behavior, socialization, and communication, highlighting its impact on neurological and cognitive functions."}]},"Energy":{"score":5,"studies":[{"title":"The effect of beta-alanine supplementation on neuromuscular fatigue in elderly (55-92 Years): a double-blind randomized study","url":"https://pubmed.ncbi.nlm.nih.gov/18544902","notes":"In an elderly population, supplementation with carnosine''s precursor was shown to significantly delay the onset of neuromuscular fatigue, which is perceived as an increase in energy and capacity for physical work."}]}}'::jsonb
WHERE id = 'l_carnosine';


UPDATE modalities 
SET 
  brief_description = 'Boost your brain''s memory recall and physical endurance today by supporting cellular energy, while activating your body''s longevity genes for long-term health.',
  expanded_why = 'Resveratrol and its more bioavailable analog, pterostilbene, are potent polyphenols that activate SIRT1, a key ''longevity gene'' involved in DNA repair, metabolic regulation, and inflammation control. By mimicking aspects of caloric restriction, they support mitochondrial function and protect cells from oxidative stress, thereby promoting metabolic health and cellular resilience.',
  functional_impacts = '{"Memory":{"score":7,"studies":[{"title":"Effects of resveratrol on memory performance, hippocampal functional connectivity, and glucose metabolism in healthy older adults","url":"https://pubmed.ncbi.nlm.nih.gov/24899704/","notes":"This randomized controlled trial demonstrated that 26 weeks of resveratrol supplementation significantly improved memory retention and hippocampal functional connectivity in healthy, overweight older adults."}]},"Joint Comfort":{"score":6,"studies":[{"title":"Resveratrol as an effective adjuvant therapy in the management of knee osteoarthritis: a randomized, double-blind, placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/30425553/","notes":"This clinical trial found that resveratrol supplementation significantly reduced pain scores and improved physical function in patients with mild to moderate knee osteoarthritis compared to a placebo group."}]},"Endurance":{"score":5,"studies":[{"title":"Resveratrol Enhances Exercise-Induced Cellular and Functional Adaptations in Older Adults","url":"https://pubmed.ncbi.nlm.nih.gov/28383849/","notes":"In older adults, resveratrol supplementation combined with exercise training improved walking endurance and mitochondrial respiration significantly more than exercise alone, indicating enhanced adaptation to physical activity."}]}}'::jsonb
