UPDATE modalities 
SET 
  brief_description = 'Boost your body''s natural detoxification pathways today to reduce inflammation and clear cellular waste, which over time supports healthy aging and reduces cancer risk.',
  expanded_why = 'Sulforaphane is a potent isothiocyanate that activates the Nrf2 pathway, a master regulator of the body''s antioxidant and detoxification systems. This activation upregulates hundreds of protective genes, including those for antioxidant enzymes like glutathione, effectively enhancing cellular defense against oxidative stress and inflammation. By promoting the elimination of toxins and carcinogens, Sulforaphane supports cellular integrity and long-term health.',
  functional_impacts = '{"Brain Fog":{"score":7,"studies":[{"title":"Sulforaphane treatment of autism spectrum disorder (ASD)","url":"https://pubmed.ncbi.nlm.nih.gov/25225382/","notes":"A placebo-controlled trial in young men with ASD found that sulforaphane treatment led to substantial improvements in behavior, social interaction, and verbal communication, suggesting a reduction in factors contributing to brain fog."}]},"Joint Comfort":{"score":7,"studies":[{"title":"Sulforaphane represses matrix-degrading proteases in articular chondrocytes to protect cartilage from destruction","url":"https://pubmed.ncbi.nlm.nih.gov/23982885/","notes":"This foundational study showed that sulforaphane blocks key enzymes that cause cartilage destruction in osteoarthritis and protects against inflammation, demonstrating a direct mechanism for improving joint health and comfort."}]},"Mood":{"score":6,"studies":[{"title":"Sulforaphane reduces anxiety and depressive-like behavior in mice","url":"https://pubmed.ncbi.nlm.nih.gov/32959828/","notes":"This preclinical study found that sulforaphane administration reversed depressive and anxiety-like behaviors by reducing neuroinflammation and oxidative stress, highlighting its potential mood-stabilizing effects."}]},"Immune Resilience":{"score":8,"studies":[{"title":"Effect of sulforaphane on non-specific immunity and gut microbiome in stressed mice","url":"https://pubmed.ncbi.nlm.nih.gov/31336997/","notes":"This study showed that sulforaphane alleviated stress-induced immunosuppression by improving spleen and thymus indices, enhancing NK cell activity, and positively modulating the gut microbiota, thereby bolstering overall immune resilience."}]}}'::jsonb
WHERE id = 'sulforaphane';


UPDATE modalities 
SET 
  brief_description = 'Enhance your memory recall and focus today with Bacopa Monnieri, an Ayurvedic adaptogen that also protects your brain cells from age-related stress to support long-term cognitive health.',
  expanded_why = 'Bacopa Monnieri''s primary active compounds, bacosides, enhance neuronal communication by promoting nerve ending growth and modulating key neurotransmitter systems like acetylcholine and serotonin. This improves synaptic function while its potent antioxidant properties protect brain cells from oxidative damage, a key mechanism in cognitive aging.',
  functional_impacts = '{"Memory":{"score":8,"studies":[{"title":"The chronic effects of an extract of Bacopa monniera (Brahmi) on cognitive function in healthy human subjects","url":"https://pubmed.ncbi.nlm.nih.gov/11498727","notes":"This landmark double-blind RCT found that 12 weeks of Bacopa supplementation (300 mg/day) significantly improved the rate of learning, memory consolidation, and information processing in healthy adults."}]},"Focus":{"score":7,"studies":[{"title":"Effects of 12-Week Bacopa monnieri Consumption on Attention, Cognitive Processing, Working Memory, and Functions of both Cholinergic and Monoaminergic Systems in Healthy Elderly Volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/22746404","notes":"In this randomized, placebo-controlled trial, elderly participants taking Bacopa for 12 weeks showed significant improvements in attention and cognitive processing speed compared to placebo."}]},"Stress":{"score":6,"studies":[{"title":"Effects of a standardized Bacopa monnieri extract on cognitive performance, anxiety, and depression in the elderly: a randomized, double-blind, placebo-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/18611150","notes":"This 12-week RCT demonstrated that Bacopa extract significantly reduced scores on anxiety scales in participants over 65, highlighting its adaptogenic and anxiolytic properties."}]}}'::jsonb
