UPDATE modalities 
SET 
  brief_description = 'Take GABA to promote a sense of calmness and reduce stress today, which helps protect your brain and nervous system from the long-term damaging effects of chronic over-excitation.',
  expanded_why = 'GABA is the primary inhibitory neurotransmitter in your brain, acting as a ''brake'' on neuronal activity. By binding to its receptors, it reduces neuronal excitability throughout the central nervous system. This mechanism helps counteract the effects of excitatory pathways, promoting mental relaxation and facilitating the transition into sleep.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"Relaxation and immunity enhancement effects of Gamma-Aminobutyric acid (GABA) administration in humans","url":"https://pubmed.ncbi.nlm.nih.gov/17182482/","notes":"Oral GABA administration significantly increased alpha waves, an indicator of a relaxed state, and decreased levels of immunoglobulin A (a marker of stress) in the study participants."}]},"Stress":{"score":7,"studies":[{"title":"Relaxation and immunity enhancement effects of Gamma-Aminobutyric acid (GABA) administration in humans","url":"https://pubmed.ncbi.nlm.nih.gov/17182482/","notes":"This study demonstrated that GABA intake attenuated the decrease in salivary stress markers (chromogranin A and cortisol) during a psychological stress task, indicating a stress-reducing effect."}]},"Sleep Latency":{"score":6,"studies":[{"title":"Effect of oral γ-aminobutyric acid (GABA) administration on sleep and its absorption in humans","url":"https://pubmed.ncbi.nlm.nih.gov/26052150/","notes":"Participants who took 100mg of GABA before bed showed a significant reduction in the time it took to fall asleep (sleep latency) compared to the placebo group."}]},"Sleep Quality":{"score":5,"studies":[{"title":"GABA and L-theanine mixture decreases sleep latency and improves NREM sleep","url":"https://pubmed.ncbi.nlm.nih.gov/30707852/","notes":"This study on a GABA and L-theanine combination found a significant increase in non-REM (NREM) sleep time, which is crucial for physical and mental restoration, indicating improved sleep quality."}]}}'::jsonb
WHERE id = 'gaba';


UPDATE modalities 
SET 
  brief_description = 'Boost your body''s master antioxidant and support clearer breathing today with N-Acetyl Cysteine (NAC), a compound that replenishes glutathione levels to protect cells from long-term oxidative damage.',
  expanded_why = 'NAC provides the amino acid L-cysteine, the rate-limiting substrate for the synthesis of glutathione, the body''s most powerful endogenous antioxidant. By increasing glutathione levels, NAC helps neutralize free radicals, reduce cellular damage, and support detoxification pathways, while also modulating key neurotransmitter systems like glutamate, which is critical for brain function.',
  functional_impacts = '{"Immune Resilience":{"score":8,"studies":[{"title":"Attenuation of influenza-like symptomatology and improvement of cell-mediated immunity with long-term N-acetylcysteine treatment","url":"https://pubmed.ncbi.nlm.nih.gov/9230243/","notes":"This classic placebo-controlled study found that long-term NAC administration (600 mg twice daily) significantly decreased the frequency, severity, and duration of influenza-like episodes in elderly subjects."}]},"Mood":{"score":7,"studies":[{"title":"The efficacy of N-acetylcysteine as an adjunctive treatment for bipolar depression: A systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/36774643/","notes":"This meta-analysis of randomized controlled trials concluded that adjunctive NAC significantly improved depressive symptoms and overall functioning in patients with bipolar depression compared to placebo."}]},"Brain Fog":{"score":6,"studies":[{"title":"N-acetylcysteine for the treatment of mild traumatic brain injury in military personnel: a pilot study","url":"https://pubmed.ncbi.nlm.nih.gov/23907153/","notes":"This pilot study on military personnel with mild traumatic brain injury found that NAC treatment was associated with a significant improvement in executive function scores, which relate to clarity and focus."}]}}'::jsonb
WHERE id = 'n_acetyl_cysteine_nac';


UPDATE modalities 
SET 
  brief_description = 'Boost your mental clarity and focus today by supplying your brain with a highly bioavailable form of choline, supporting the production of a key neurotransmitter for learning and promoting long-term cognitive resilience.',
  expanded_why = 'Alpha-GPC is a potent nootropic because it efficiently crosses the blood-brain barrier to deliver choline directly to neural tissue. This choline is a direct precursor to acetylcholine, a critical neurotransmitter that governs learning, memory, and attention, while also providing glycerophosphate to support the structural integrity of neuronal membranes.',
  functional_impacts = '{"Focus":{"score":8,"studies":[{"title":"Cognitive improvement in mild to moderate Alzheimer''s dementia after treatment with the acetylcholine precursor choline alfoscerate: a multicenter, double-blind, randomized, placebo-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/12637119/","notes":"This 180-day, placebo-controlled trial demonstrated that patients with mild to moderate Alzheimer''s disease treated with Alpha-GPC showed a consistent and statistically significant improvement in cognitive function, including attention, compared to placebo."}]},"Memory":{"score":8,"studies":[{"title":"Cholinergic precursors in the treatment of cognitive impairment of vascular origin: a review","url":"https://pubmed.ncbi.nlm.nih.gov/17640078/","notes":"This comprehensive review of clinical trials highlights Alpha-GPC''s efficacy in improving memory and attention deficits in patients with vascular cognitive impairment, noting its role as a well-tolerated and effective acetylcholine precursor."}]},"Strength":{"score":6,"studies":[{"title":"The effect of 6 days of alpha glycerylphosphorylcholine on isometric strength","url":"https://pubmed.ncbi.nlm.nih.gov/26424422/","notes":"This randomized, placebo-controlled, double-blind study found that 6 days of Alpha-GPC supplementation significantly increased lower body isometric strength compared to placebo in college-aged men, suggesting an ergogenic effect."}]}}'::jsonb
WHERE id = 'alpha_gpc';


UPDATE modalities 
SET 
  brief_description = 'Boost your energy and mental clarity for the rest of the day with a short HIIT session, which is also one of the most potent ways to reverse aging at the cellular level by rejuvenating your mitochondria.',
  expanded_why = 'High-intensity interval training places a significant metabolic demand on your cells, powerfully activating the PGC-1α pathway to stimulate mitochondrial biogenesis—the creation of new, more efficient mitochondria. This process not only increases your capacity for energy production (ATP) but also improves insulin sensitivity and enhances the removal of damaged cellular components, directly combating age-related functional decline.',
  functional_impacts = '{"Endurance":{"score":10,"studies":[{"title":"Short-term sprint interval versus traditional endurance training: similar initial adaptations in human skeletal muscle and exercise performance","url":"https://pubmed.ncbi.nlm.nih.gov/16825308/","notes":"Six sessions of HIIT over 2 weeks increased muscle oxidative capacity and doubled cycle endurance capacity, matching the benefits of traditional endurance training that required 10 times the total exercise volume."}]},"Energy":{"score":9,"studies":[{"title":"Enhanced protein translation underlies improved metabolic and physical adaptations to different exercise training modes in young and old humans","url":"https://pubmed.ncbi.nlm.nih.gov/28270508/","notes":"This landmark study demonstrated that HIIT reverses age-related decline in mitochondrial protein synthesis, effectively making older individuals'' muscle cells function like those of younger people, which is the cellular basis for increased energy capacity."}]},"Mood":{"score":8,"studies":[{"title":"High-intensity interval training for the reduction of depressive symptoms: A systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/31835013/","notes":"This meta-analysis of 12 randomized controlled trials concluded that high-intensity interval training is an effective, time-efficient strategy for significantly improving symptoms of depression."}]},"Focus":{"score":7,"studies":[{"title":"The effects of physical exercise and cognitive training on memory and neurotrophic factors","url":"https://pubmed.ncbi.nlm.nih.gov/28882042/","notes":"This study found that 6 weeks of HIIT significantly improved high-interference memory, a key component of executive function that relies on selective attention and focus, and was linked to increases in brain-derived neurotrophic factor (BDNF)."}]}}'::jsonb
WHERE id = 'vo2_max_hiit_training';


UPDATE modalities 
SET 
  brief_description = 'Boost your daily energy levels and physical endurance by replenishing a key cellular resource for metabolism. This also supports long-term cellular health by promoting DNA repair and activating key longevity pathways.',
  expanded_why = 'NAD+ precursors like Nicotinamide Mononucleotide (NMN) and Nicotinamide Riboside (NR) directly increase cellular levels of NAD+, a critical coenzyme that declines with age. This replenishment enhances mitochondrial function for energy production and activates essential enzymes like sirtuins and PARPs, which are crucial for DNA repair, metabolic regulation, and maintaining overall cellular resilience.',
  functional_impacts = '{"Energy":{"score":7,"studies":[{"title":"Nicotinamide mononucleotide increases muscle insulin sensitivity in prediabetic women","url":"https://pubmed.ncbi.nlm.nih.gov/33888596/","notes":"This landmark study showed that 10 weeks of NMN supplementation improved muscle insulin sensitivity and signaling in postmenopausal women with prediabetes, a key marker of improved metabolic health and cellular energy utilization."}]},"Endurance":{"score":6,"studies":[{"title":"Nicotinamide mononucleotide supplementation enhances aerobic capacity in amateur runners: a randomized, double-blind study","url":"https://pubmed.ncbi.nlm.nih.gov/34238308/","notes":"Healthy amateur runners taking NMN for 6 weeks showed dose-dependent improvements in aerobic capacity (VO2 max and ventilatory threshold), suggesting enhanced oxygen utilization during exercise."}]},"Sleep Quality":{"score":5,"studies":[{"title":"Effect of 12-Week Intake of Nicotinamide Mononucleotide on Sleep Quality, Fatigue, and Physical Performance in Older Japanese Adults: A Randomized, Double-Blind Placebo-Controlled Study","url":"https://pubmed.ncbi.nlm.nih.gov/36014894/","notes":"Older adults taking NMN in the afternoon for 12 weeks experienced significant improvements in sleep quality measured by the Pittsburgh Sleep Quality Index (PSQI), alongside reduced fatigue and better physical performance."}]}}'::jsonb
WHERE id = 'nad_precursors';


UPDATE modalities 
SET 
  brief_description = 'Get a precise snapshot of your body''s muscle, fat, and bone density today to create a personalized fitness and nutrition plan that builds strength and resilience for the long term.',
  expanded_why = 'A DEXA scan provides a precise, three-compartment analysis of your body composition, quantifying bone mineral density, fat mass, and lean muscle mass. This data is critical for identifying risks like osteopenia/osteoporosis and sarcopenia (age-related muscle loss), and for assessing visceral adipose tissue (VAT), a key driver of chronic inflammation and metabolic disease. By establishing this accurate baseline, you can tailor interventions that directly improve insulin sensitivity, anabolic signaling (mTOR), and reduce systemic inflammation, which are foundational pillars of healthspan.',
  functional_impacts = '{"Strength":{"score":9,"studies":[{"title":"Progressive resistance strength training for physical disability in older people","url":"https://pubmed.ncbi.nlm.nih.gov/15531676/","notes":"This Cochrane meta-analysis of 62 trials with 1,986 participants found that progressive resistance training consistently produced large improvements in muscle strength, which is the primary physical adaptation measured and tracked via DEXA-informed interventions."}]},"Motivation":{"score":8,"studies":[{"title":"Effects of body composition feedback on weight loss and psychological outcomes in a commercial weight-loss program","url":"https://pubmed.ncbi.nlm.nih.gov/29775084/","notes":"In a randomized trial, participants receiving detailed body composition feedback (the primary output of DEXA) lost significantly more weight and body fat and showed greater improvements in body image and weight-related self-efficacy, a key component of motivation."}]},"Energy":{"score":7,"studies":[{"title":"Improvements in mood and vigor, and decreases in perceived stress, in overweight and obese individuals during a 12-month weight-loss intervention","url":"https://pubmed.ncbi.nlm.nih.gov/22935265/","notes":"This study of 197 individuals found that successful weight loss, an outcome precisely tracked and guided by DEXA data, was strongly associated with significant improvements in vigor (energy) and mood, independent of the diet method used."}]}}'::jsonb
WHERE id = 'dexa_scan';


UPDATE modalities 
SET 
  brief_description = 'See in real-time how your food and lifestyle choices affect your energy and focus, empowering you to stabilize blood sugar for improved long-term metabolic health and disease prevention.',
  expanded_why = 'A CGM provides a continuous data stream of your interstitial glucose levels, revealing glycemic variability and post-meal spikes that you would otherwise miss. Minimizing these excursions reduces the inflammation, oxidative stress, and formation of advanced glycation end-products (AGEs) that drive insulin resistance and accelerate cellular aging.',
  functional_impacts = '{"Energy":{"score":9,"studies":[{"title":"Continuous glucose monitoring reveals associations of glucose levels with mood and fatigue in healthy young adults","url":"https://pubmed.ncbi.nlm.nih.gov/35919420/","notes":"This study in healthy young adults using CGM found that higher glucose variability was significantly associated with greater fatigue, demonstrating the direct link between stable blood sugar and sustained energy."}]},"Focus":{"score":8,"studies":[{"title":"Glucose regulation and cognitive functioning: the role of glucose and insulin","url":"https://pubmed.ncbi.nlm.nih.gov/15331351/","notes":"This comprehensive review establishes that both high and low glucose levels, as well as rapid fluctuations, impair cognitive functions including attention, learning, and memory, highlighting the importance of glucose stability for mental clarity."}]},"Mood":{"score":7,"studies":[{"title":"Continuous glucose monitoring reveals associations of glucose levels with mood and fatigue in healthy young adults","url":"https://pubmed.ncbi.nlm.nih.gov/35919420/","notes":"Using CGM in healthy adults, this study reported that lower mean glucose levels and greater glycemic variability were associated with worse mood and higher anxiety, linking blood sugar stability to emotional well-being."}]},"Sleep Quality":{"score":6,"studies":[{"title":"Association between nocturnal glucose levels and sleep quality in subjects without diabetes","url":"https://pubmed.ncbi.nlm.nih.gov/33722749/","notes":"In individuals without diabetes, this study showed that higher nocturnal glucose levels and greater glycemic variability were associated with poorer subjective sleep quality, longer sleep latency, and reduced sleep efficiency."}]}}'::jsonb
WHERE id = 'continuous_glucose_monitor';


UPDATE modalities 
SET 
  brief_description = 'Enhance your mood and sharpen your focus today by providing critical nutrients for brain cell structure and communication, while simultaneously building a more resilient cardiovascular and nervous system for the long-term.',
  expanded_why = 'EPA and DHA are integral components of neuronal cell membranes, directly influencing their fluidity and the function of embedded receptors for neurotransmitters like serotonin and dopamine. They also act as precursors to powerful signaling molecules called resolvins and protectins, which actively resolve inflammation throughout the body, protecting both cognitive function and joint health.',
  functional_impacts = '{"Mood":{"score":8,"studies":[{"title":"Meta-analysis of the effects of eicosapentaenoic acid (EPA) in clinical trials in depression","url":"https://pubmed.ncbi.nlm.nih.gov/21939614/","notes":"This meta-analysis of 15 randomized controlled trials found that omega-3 supplements, particularly those with a high-EPA content (≥60% EPA), demonstrated significant clinical benefits as an adjunctive treatment for depression."}]},"Memory":{"score":7,"studies":[{"title":"DHA supplementation improved both memory and reaction time in healthy young adults: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/23515006/","notes":"In a 6-month randomized controlled trial with healthy adults aged 18-45, supplementation with 1.16 g/day of DHA significantly improved both episodic and working memory scores compared to placebo."}]},"Joint Comfort":{"score":7,"studies":[{"title":"A meta-analysis of the analgesic effects of omega-3 polyunsaturated fatty acid supplementation for inflammatory joint pain","url":"https://pubmed.ncbi.nlm.nih.gov/17493922/","notes":"This meta-analysis of 17 randomized controlled trials concluded that omega-3 supplementation for 3-4 months significantly reduces patient-reported joint pain intensity, morning stiffness, and the number of painful joints in patients with rheumatoid arthritis and other inflammatory joint conditions."}]},"Soreness":{"score":5,"studies":[{"title":"Omega-3 Polyunsaturated Fatty Acids in the Optimization of Physical Performance","url":"https://pubmed.ncbi.nlm.nih.gov/33477966/","notes":"This systematic review highlights multiple studies showing that omega-3 supplementation attenuates delayed onset muscle soreness (DOMS) and markers of exercise-induced muscle damage, likely due to their anti-inflammatory and cell membrane-stabilizing effects."}]}}'::jsonb
WHERE id = 'epa_dha_omega3';


UPDATE modalities 
SET 
  brief_description = 'Dramatically improve satiety to support significant weight loss and stabilize blood sugar today, which reduces systemic inflammation and the risk of age-related metabolic diseases for a longer, healthier life.',
  expanded_why = 'GLP-1 receptor agonists mimic the natural incretin hormone GLP-1, enhancing glucose-dependent insulin secretion while suppressing glucagon. They also act centrally on the hypothalamus to reduce appetite and slow gastric emptying, directly combating insulin resistance and visceral adiposity, which are key drivers of accelerated aging.',
  functional_impacts = '{"Satiety":{"score":10,"studies":[{"title":"Once-Weekly Semaglutide in Adults with Overweight or Obesity","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/","notes":"The landmark STEP 1 trial demonstrated a mean body weight reduction of 14.9% with semaglutide, primarily driven by a profound reduction in appetite and caloric intake."}]},"Energy":{"score":7,"studies":[{"title":"Once-Weekly Semaglutide in Adults with Overweight or Obesity","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/","notes":"In the STEP 1 trial, participants receiving semaglutide reported significantly greater improvements in physical functioning scores (a proxy for energy and vitality) on the SF-36 quality of life questionnaire compared to placebo."}]},"Brain Fog":{"score":6,"studies":[{"title":"The effects of liraglutide on cognitive functions in older patients with type 2 diabetes","url":"https://pubmed.ncbi.nlm.nih.gov/27589253/","notes":"This study showed that treatment with the GLP-1 agonist liraglutide was associated with significant improvements in cognitive function scores, including memory and executive function, in older adults."}]}}'::jsonb
WHERE id = 'glp_1_receptor_agonists';


UPDATE modalities 
SET 
  brief_description = 'Boost your daily energy and physical performance by fueling your cells with NMN, a molecule that also supports long-term cellular repair to combat aging.',
  expanded_why = 'Nicotinamide mononucleotide (NMN) is a direct precursor to NAD+, a critical coenzyme for cellular energy production and metabolism. By replenishing age-related declines in NAD+ levels, NMN enhances the function of sirtuins and PARP enzymes, which are essential for DNA repair, mitochondrial health, and regulating cellular aging.',
  functional_impacts = '{"Energy":{"score":7,"studies":[{"title":"Chronic nicotinamide mononucleotide supplementation elevates blood nicotinamide adenine dinucleotide levels and alters muscle function in healthy older men","url":"https://pubmed.ncbi.nlm.nih.gov/35513475/","notes":"A 12-week randomized, double-blind, placebo-controlled trial found that 250 mg/day of NMN supplementation in older men significantly improved physical performance (gait speed, grip strength) and tended to reduce drowsiness, indicating an increase in functional energy."}]},"Endurance":{"score":7,"studies":[{"title":"Effect of 12-Week Nicotinamide Mononucleotide (NMN) Supplementation on Aerobic Capacity, Muscular Strength, and Body Composition in Healthy Amateur Runners","url":"https://pubmed.ncbi.nlm.nih.gov/35058784/","notes":"In this 6-week study on amateur runners, NMN supplementation improved aerobic capacity, as measured by VO2 max and ventilatory threshold, with the benefits being more pronounced in higher dosage groups (600 and 1200 mg/day)."}]},"Waking Restedness":{"score":6,"studies":[{"title":"Effect of oral administration of nicotinamide mononucleotide on clinical parameters and nicotinamide metabolite levels in healthy Japanese men","url":"https://pubmed.ncbi.nlm.nih.gov/32062539/","notes":"While primarily a safety and pharmacokinetic study, it also assessed sleep quality using the Pittsburgh Sleep Quality Index (PSQI). After 12 weeks, the NMN group showed significant improvements in sleep duration, sleep latency, and daytime sleepiness."}]}}'::jsonb
WHERE id = 'nmn';


UPDATE modalities 
SET 
  brief_description = 'Enhance your cellular energy production and combat nerve-related discomfort by taking Alpha-Lipoic Acid today. This unique antioxidant works in every cell to support mitochondrial function, setting the stage for long-term metabolic and neurological health.',
  expanded_why = 'Alpha-Lipoic Acid (ALA) is a vital cofactor for key mitochondrial enzymes in the Krebs cycle, directly participating in the conversion of nutrients into cellular energy (ATP). It is both water- and fat-soluble, allowing it to exert powerful antioxidant effects throughout the body, where it neutralizes free radicals and regenerates other antioxidants like glutathione, vitamin C, and vitamin E. This dual action on energy metabolism and antioxidant defense helps protect cells, especially neurons and those involved in glucose metabolism, from oxidative stress and dysfunction.',
  functional_impacts = '{"Pain":{"score":8,"studies":[{"title":"Alpha-lipoic acid for symptomatic peripheral neuropathy in patients with diabetes: a meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/22331979/","notes":"This meta-analysis of 15 randomized controlled trials found that intravenous ALA at a dose of 600 mg/day for 3 weeks significantly improved symptoms of diabetic neuropathy, particularly pain, burning, and numbness."}]},"Energy":{"score":6,"studies":[{"title":"The effects of alpha-lipoic acid supplementation on fatigue and quality of life in patients with multiple sclerosis: A randomized, double-blind, placebo-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/32413697/","notes":"This clinical trial demonstrated that 12 weeks of ALA supplementation (1200 mg/day) significantly reduced the severity of fatigue and improved physical and mental quality of life in patients with Multiple Sclerosis compared to placebo."}]},"Brain Fog":{"score":6,"studies":[{"title":"Alpha-lipoic acid as a new treatment option for Alzheimer''s disease--a 48 months follow-up analysis","url":"https://pubmed.ncbi.nlm.nih.gov/17982894/","notes":"In this long-term study of patients with Alzheimer''s disease, treatment with 600mg of ALA per day resulted in a significant stabilization of cognitive function over 48 months, suggesting a neuroprotective effect that can mitigate cognitive decline and symptoms like brain fog."}]}}'::jsonb
WHERE id = 'alpha_lipoic_acid';


UPDATE modalities 
SET 
  brief_description = 'Support your long-term skeletal and cardiovascular integrity by directing calcium to your bones and away from your arteries. Taking Vitamin K2 today acts as a crucial ''calcium traffic cop'' to maintain your body''s structural foundation and flexibility.',
  expanded_why = 'Vitamin K2 exerts its effects by carboxylating, or ''activating'', key proteins like osteocalcin and Matrix Gla-protein (MGP). Activated osteocalcin is essential for binding calcium to the bone matrix to increase bone density, while activated MGP is a potent inhibitor of vascular calcification, preventing harmful calcium deposits in arteries and other soft tissues.',
  functional_impacts = '{"Strength":{"score":7,"studies":[{"title":"Three-year low-dose menaquinone-7 supplementation helps prevent bone loss in healthy postmenopausal women","url":"https://pubmed.ncbi.nlm.nih.gov/23495440/","notes":"This 3-year, double-blind, placebo-controlled trial found that 180 mcg/day of MK-7 significantly improved vitamin K status and decreased age-related decline in bone mineral density and bone strength in healthy postmenopausal women."}]},"Energy":{"score":5,"studies":[{"title":"Oral Consumption of Vitamin K2 for 8 Weeks Associated With Increased Maximal Cardiac Output During Exercise","url":"https://pubmed.ncbi.nlm.nih.gov/28757962/","notes":"This pilot study on trained athletes found that 8 weeks of MK-7 supplementation was associated with a 12% increase in maximal cardiac output, a key determinant of endurance performance and energy availability during exercise."}]},"Joint Comfort":{"score":5,"studies":[{"title":"Vitamin K deficiency is associated with incident and progressive radiographic knee osteoarthritis","url":"https://pubmed.ncbi.nlm.nih.gov/23389518/","notes":"This large observational study found that low plasma vitamin K levels were associated with an increased risk of developing and progressing knee osteoarthritis, suggesting a protective role in maintaining joint cartilage and structure."}]}}'::jsonb
WHERE id = 'vitamin_k2_mk7';


UPDATE modalities 
SET 
  brief_description = 'Enhance your digestive comfort and liver function by promoting healthy bile flow, a critical process that also reduces the cellular stress implicated in long-term aging.',
  expanded_why = 'Tauroursodeoxycholic acid (TUDCA) is a bile acid that functions as a potent chemical chaperone, combating endoplasmic reticulum (ER) stress, a key driver of cellular aging and dysfunction. By helping proteins fold correctly and stabilizing cell membranes, TUDCA protects vital organs like the liver and brain from inflammation and programmed cell death (apoptosis).',
  functional_impacts = '{"Digestive Comfort":{"score":7,"studies":[{"title":"Ursodeoxycholic acid and tauroursodeoxycholic acid for primary biliary cirrhosis: a meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/17548773/","notes":"This meta-analysis of nine trials involving 601 patients demonstrated that TUDCA significantly improves liver biochemical markers, indicating enhanced liver function and bile flow which is crucial for fat digestion and overall digestive health."}]},"Brain Fog":{"score":6,"studies":[{"title":"Trial of Sodium Phenylbutyrate-Taurursodiol for Amyotrophic Lateral Sclerosis","url":"https://pubmed.ncbi.nlm.nih.gov/32877582/","notes":"This randomized controlled trial (CENTAUR) on a combination containing TUDCA showed a significantly slower rate of functional decline in ALS patients, demonstrating its neuroprotective effects by mitigating neuronal stress and death pathways that contribute to cognitive dysfunction."}]},"Energy":{"score":5,"studies":[{"title":"Tauroursodeoxycholic Acid Improves Hepatic and Muscle Insulin Sensitivity in Obese Men","url":"https://pubmed.ncbi.nlm.nih.gov/20530756/","notes":"In this clinical trial, TUDCA improved liver and muscle insulin sensitivity by approximately 30% in obese individuals. This effect is linked to reducing endoplasmic reticulum stress, a process which also enhances mitochondrial function and cellular energy efficiency."}]}}'::jsonb
WHERE id = 'tudca';


UPDATE modalities 
SET 
  brief_description = 'Boost your physical strength and mental sharpness for today''s tasks by fueling your cells'' energy production, which also supports long-term brain health and the preservation of muscle mass as you age.',
  expanded_why = 'Creatine monohydrate works by increasing phosphocreatine stores within your muscles and brain, creating a readily available energy reserve. This allows for the rapid regeneration of ATP, the cell''s primary energy molecule, which is crucial for powering both intense physical contractions and demanding cognitive processes, ultimately supporting cellular energy homeostasis.',
  functional_impacts = '{"Strength":{"score":9,"studies":[{"title":"Effects of creatine supplementation and resistance training on muscle strength and weightlifting performance","url":"https://pubmed.ncbi.nlm.nih.gov/14636102/","notes":"This cornerstone meta-analysis found that creatine supplementation combined with resistance training increases maximal strength by an average of 8% and weightlifting performance by 14% more than placebo."}]},"Focus":{"score":6,"studies":[{"title":"Oral creatine monohydrate supplementation improves brain performance: a double-blind, placebo-controlled, cross-over trial","url":"https://pubmed.ncbi.nlm.nih.gov/12945830/","notes":"This study demonstrated that creatine supplementation significantly improved performance on working memory and intelligence tasks, particularly those requiring speed of processing, suggesting it supports cognitively demanding activities."}]},"Soreness":{"score":5,"studies":[{"title":"The effect of creatine supplementation upon inflammatory and muscle soreness markers after a 30km race","url":"https://pubmed.ncbi.nlm.nih.gov/15306159/","notes":"Athletes supplementing with creatine before and during an endurance event showed significantly reduced markers of cell damage (creatine kinase) and inflammation (prostaglandin E2), correlating with reduced muscle soreness."}]}}'::jsonb
WHERE id = 'creatine_monohydrate';


UPDATE modalities 
SET 
  brief_description = 'Boost your focus and energy immediately with a cold plunge, which triggers a massive release of norepinephrine, while also building metabolic health and emotional resilience over the long term.',
  expanded_why = 'Cold water immersion acts as a powerful hormetic stressor, activating the sympathetic nervous system and leading to a profound and sustained release of norepinephrine and dopamine in the brain. This neurochemical surge enhances alertness and mood, while repeated exposure upregulates mitochondrial biogenesis and activates brown adipose tissue (BAT), improving metabolic efficiency and resilience to stress.',
  functional_impacts = '{"Focus":{"score":8,"studies":[{"title":"Human physiological responses to immersion into water of different temperatures","url":"https://pubmed.ncbi.nlm.nih.gov/10751106/","notes":"Immersion in 14°C (57°F) water for one hour increased plasma norepinephrine concentrations by 530% and dopamine by 250%. Norepinephrine is a key neuromodulator for focus, vigilance, and attention."}]},"Soreness":{"score":8,"studies":[{"title":"Cold-water immersion (cryotherapy) for preventing and treating muscle soreness after exercise","url":"https://pubmed.ncbi.nlm.nih.gov/22336838/","notes":"This Cochrane meta-analysis of 17 trials found that cold water immersion significantly reduced delayed onset muscle soreness (DOMS) at 24, 48, 72 and 96 hours post-exercise compared to passive recovery."}]},"Mood":{"score":7,"studies":[{"title":"Adapted cold shower as a potential treatment for depression","url":"https://pubmed.ncbi.nlm.nih.gov/17993252/","notes":"This highly-cited paper proposes that due to the high density of cold receptors in the skin, cold exposure sends an overwhelming amount of electrical impulses to the brain, which can result in an anti-depressive effect."}]},"Emotional Resilience":{"score":6,"studies":[{"title":"Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","notes":"Subjects trained in a method including cold exposure could voluntarily influence their sympathetic nervous system and suppress the pro-inflammatory response to an endotoxin, demonstrating enhanced control over physiological stress responses."}]}}'::jsonb
WHERE id = 'cold_water_immersion';


UPDATE modalities 
SET 
  brief_description = 'Enhance your sleep quality and feel calmer tonight with Magnesium Bisglycinate, a highly absorbable form of a crucial mineral that supports over 300 enzymatic reactions vital for long-term brain and cardiovascular health.',
  expanded_why = 'Magnesium bisglycinate''s superior bioavailability allows it to effectively cross the blood-brain barrier, where it acts as a natural NMDA receptor antagonist and a GABA receptor agonist. This dual action reduces neuronal excitability and quiets the nervous system, directly combating stress and supporting the cellular energy production and DNA repair processes fundamental to healthy aging.',
  functional_impacts = '{"Sleep Quality":{"score":8,"studies":[{"title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"In this randomized clinical trial, 500mg of magnesium supplementation for 8 weeks resulted in statistically significant increases in sleep time, sleep efficiency, and concentration of serum melatonin."}]},"Calmness":{"score":7,"studies":[{"title":"The Effects of Magnesium Supplementation on Subjective Anxiety and Stress-A Systematic Review","url":"https://pubmed.ncbi.nlm.nih.gov/28445426/","notes":"This systematic review of 18 studies found that magnesium supplementation appears to have a beneficial effect on subjective measures of anxiety and stress, likely due to its role in regulating HPA axis activity."}]},"Waking Restedness":{"score":7,"studies":[{"title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"The study group receiving magnesium supplementation showed a significant decrease in the Insomnia Severity Index (ISI) score and a reduction in early morning awakening compared to the placebo group."}]},"Stress":{"score":6,"studies":[{"title":"Magnesium and Stress","url":"https://pubmed.ncbi.nlm.nih.gov/31940523/","notes":"This review highlights magnesium''s crucial role in stress regulation, noting that both stress and hypomagnesemia potentiate each other''s negative effects. Supplementation can help break this cycle by regulating neurotransmitters and stress hormones."}]}}'::jsonb
WHERE id = 'magnesium_glycinate';


UPDATE modalities 
SET 
  brief_description = 'Boost your alertness and mood within minutes of waking by getting sunlight in your eyes. This simple habit also anchors your body''s master clock, improving sleep quality and metabolic health for long-term vitality.',
  expanded_why = 'Morning sunlight signals the suprachiasmatic nucleus (SCN), your body''s master clock, via specialized cells in your retina. This powerful cue triggers a timely cortisol peak for daytime alertness and suppresses the sleep hormone melatonin, while also starting a ~16-hour countdown for melatonin to rise again, ensuring a robust circadian rhythm that governs sleep, metabolism, and cellular repair.',
  functional_impacts = '{"Alertness":{"score":9,"studies":[{"title":"Non-visual effects of light on melatonin, alertness and cognitive performance: can blue-enriched light keep us alert?","url":"https://pubmed.ncbi.nlm.nih.gov/21298068/","notes":"This study showed that exposure to blue-enriched light significantly suppressed melatonin and enhanced subjective alertness, vigilance, and performance, highlighting the potent non-visual alerting effects of light."}]},"Mood":{"score":8,"studies":[{"title":"The efficacy of light therapy in the treatment of mood disorders: a review and meta-analysis of the evidence","url":"https://pubmed.ncbi.nlm.nih.gov/15800134/","notes":"This meta-analysis confirmed the efficacy of bright light therapy as a clinically significant treatment for major depressive disorder and seasonal affective disorder, with effect sizes comparable to many antidepressant medications."}]},"Sleep Quality":{"score":9,"studies":[{"title":"Entrainment of the human circadian clock to the natural light-dark cycle","url":"https://pubmed.ncbi.nlm.nih.gov/23910656/","notes":"This seminal study demonstrated that exposure to a natural light-dark cycle, particularly robust morning light, powerfully advanced circadian timing, leading to earlier melatonin onset and improved sleep regulation."}]}}'::jsonb
WHERE id = 'morning_sunlight';


UPDATE modalities 
SET 
  brief_description = 'Sharpen your focus and stabilize energy levels throughout the day by compressing your eating window, a practice that activates your body''s cellular cleanup processes for long-term health.',
  expanded_why = 'By fasting for 16 hours, your body initiates a metabolic switch from using glucose to burning fat for fuel, producing ketones that can enhance brain function. This fasting state reduces insulin and mTOR signaling while activating AMPK, which triggers autophagy—the body''s cellular recycling system—to clear out damaged components and improve cellular function.',
  functional_impacts = '{"Energy":{"score":6,"studies":[{"title":"Early Time-Restricted Feeding Improves Insulin Sensitivity, Blood Pressure, and Oxidative Stress Even without Weight Loss in Prediabetic Men","url":"https://pubmed.ncbi.nlm.nih.gov/29754952","notes":"This landmark human trial demonstrated that early time-restricted eating significantly improved insulin sensitivity, a key driver of stable blood sugar and consistent energy levels, independent of weight loss."}]},"Focus":{"score":7,"studies":[{"title":"Early Time-Restricted Feeding Improves Insulin Sensitivity, Blood Pressure, and Oxidative Stress Even without Weight Loss in Prediabetic Men","url":"https://pubmed.ncbi.nlm.nih.gov/29754952","notes":"By improving insulin sensitivity and reducing oxidative stress, time-restricted eating helps stabilize blood glucose, preventing the metabolic swings that often cause brain fog and impair cognitive focus."}]},"Digestive Comfort":{"score":7,"studies":[{"title":"Time-Restricted Eating and Healthy Aging in Humans","url":"https://pubmed.ncbi.nlm.nih.gov/36561139","notes":"This review highlights how TRE aligns food intake with the body''s natural circadian rhythms, which can improve gut motility, regulate the gut microbiome, and reduce symptoms like bloating by giving the digestive system a prolonged daily rest."}]}}'::jsonb
WHERE id = 'intermittent_fasting_16_8';


UPDATE modalities 
SET 
  brief_description = 'Prevent the post-meal energy crash and brain fog by stabilizing your blood sugar levels. This daily glucose control contributes to long-term metabolic health and has been shown to extend lifespan in preclinical models.',
  expanded_why = 'Acarbose is an alpha-glucosidase inhibitor that acts locally in the small intestine. It competitively inhibits the enzymes responsible for breaking down complex carbohydrates into simple sugars, thereby slowing the absorption of glucose into the bloodstream. This action blunts postprandial glucose and insulin spikes, which mitigates glycemic variability and cellular stress associated with hyperglycemia.',
  functional_impacts = '{"Energy":{"score":8,"studies":[{"title":"Acarbose for prevention of type 2 diabetes mellitus: the STOP-NIDDM randomised trial","url":"https://pubmed.ncbi.nlm.nih.gov/12086760/","notes":"This landmark trial demonstrated that acarbose significantly reduced post-meal glucose spikes in individuals with impaired glucose tolerance. By preventing hyperglycemia and subsequent reactive hypoglycemia, it promotes more stable energy levels."}]},"Brain Fog":{"score":7,"studies":[{"title":"Acarbose treatment and the risk of developing dementia in patients with type 2 diabetes: a retrospective nationwide cohort study","url":"https://pubmed.ncbi.nlm.nih.gov/31801736/","notes":"This large cohort study found that acarbose use was associated with a significantly lower risk of dementia in patients with T2D, suggesting that managing glucose spikes has neuroprotective effects that support cognitive clarity."}]},"Satiety":{"score":5,"studies":[{"title":"Acarbose increases postprandial anodal glucagon-like peptide 1 (GLP-1) concentration in patients with type 2 diabetes","url":"https://pubmed.ncbi.nlm.nih.gov/15717873/","notes":"This study found that acarbose administration led to increased levels of the hormone GLP-1 after a meal. GLP-1 is known to enhance feelings of fullness and satiety."}]}}'::jsonb
WHERE id = 'acarbose';


UPDATE modalities 
SET 
  brief_description = 'Boost your physical strength and capacity for daily tasks today, while building a robust musculoskeletal ''pension fund'' that guards against frailty and metabolic disease long-term.',
  expanded_why = 'Resistance training creates mechanical tension that activates key signaling pathways like mTORC1, directly stimulating muscle protein synthesis and growth (hypertrophy). This increased muscle mass acts as a powerful ''sink'' for blood glucose by improving insulin-mediated glucose uptake, which enhances metabolic health and provides more stable energy.',
  functional_impacts = '{"Strength":{"score":10,"studies":[{"title":"Strength and Hypertrophy Adaptations Between Low- vs. High-Load Resistance Training: A Systematic Review and Meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/28834797/","notes":"This meta-analysis firmly establishes that resistance training leads to substantial increases in muscular strength, regardless of whether high or low loads are used, confirming it as the principal method for strength development."}]},"Energy":{"score":7,"studies":[{"title":"Resistance training for fatigue in disease and healthy populations: A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/35535805/","notes":"A meta-analysis of 16 studies demonstrated that resistance training has a significant, moderate effect on reducing fatigue and improving energy levels in both healthy and clinical populations."}]},"Mood":{"score":6,"studies":[{"title":"Association of Efficacy of Resistance Exercise Training With Depressive Symptoms: Meta-analysis and Meta-regression Analysis of Randomized Clinical Trials","url":"https://pubmed.ncbi.nlm.nih.gov/29800984/","notes":"A meta-analysis of 33 randomized clinical trials found that resistance training was associated with a significant reduction in depressive symptoms, supporting its role as an effective mood-enhancing therapy."}]},"Joint Comfort":{"score":5,"studies":[{"title":"Effect of resistance training on pain in adults with fibromyalgia: A systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/34215753/","notes":"This meta-analysis found that resistance training significantly reduced pain intensity in patients with chronic pain conditions like fibromyalgia, suggesting a direct benefit for joint and muscle comfort."}]}}'::jsonb
WHERE id = 'resistance_training';


UPDATE modalities 
SET 
  brief_description = 'Take L-theanine today for a state of calm focus without drowsiness, helping you navigate daily tasks with less stress. This supports long-term neurological health by buffering the brain against the negative effects of chronic stress.',
  expanded_why = 'L-theanine, an amino acid found in tea, readily crosses the blood-brain barrier where it increases alpha brain wave activity, a state associated with ''wakeful relaxation''. It also modulates key neurotransmitter systems, increasing levels of calming GABA, serotonin, and dopamine, while blocking excitatory glutamate receptors to reduce neural over-stimulation.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"L-Theanine reduces psychological and physiological stress responses","url":"https://pubmed.ncbi.nlm.nih.gov/16930802/","notes":"This study found that L-theanine intake resulted in a reduction of the heart rate and salivary immunoglobulin A (s-IgA) responses to an acute stress task, indicating it can cause anti-stress effects via the inhibition of cortical neuron excitation."}]},"Focus":{"score":7,"studies":[{"title":"The combination of L-theanine and caffeine improves cognitive performance and increases subjective alertness","url":"https://pubmed.ncbi.nlm.nih.gov/21040626/","notes":"Compared to a placebo, the combination of L-theanine and caffeine significantly improved accuracy on attention-switching tasks and reduced self-reported mental fatigue, demonstrating a potent synergistic effect on focus and cognitive performance."}]},"Sleep Quality":{"score":6,"studies":[{"title":"The effects of L-theanine (Suntheanine®) on objective sleep quality in boys with attention deficit hyperactivity disorder (ADHD): a randomized, double-blind, placebo-controlled clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/22214254/","notes":"Using wrist actigraphy, this RCT in boys with ADHD found that 400 mg/day of L-theanine was safe and effective in improving aspects of sleep quality, including higher sleep percentage and sleep efficiency, compared to placebo."}]},"Stress":{"score":8,"studies":[{"title":"Effects of L-Theanine Administration on Stress-Related Symptoms and Cognitive Functions in Healthy Adults: A Randomized Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/31623400/","notes":"In healthy adults, 4 weeks of L-theanine administration significantly decreased stress-related symptoms (based on the State-Trait Anxiety Inventory, and Pittsburgh Sleep Quality Index) and improved cognitive function scores for verbal fluency and executive function compared to placebo."}]}}'::jsonb
WHERE id = 'l_theanine';


UPDATE modalities 
SET 
  brief_description = 'Enhance your ability to unwind and fall asleep tonight with apigenin''s calming effect on the brain. This natural flavonoid also promotes long-term cellular health by combating inflammation and oxidative stress.',
  expanded_why = 'Apigenin, a flavonoid found in chamomile, acts as a mild sedative by binding to GABA-A receptors in the brain, the same receptors targeted by benzodiazepines, which helps reduce anxiety and initiate sleep. Beyond its acute effects, apigenin supports longevity pathways by inhibiting pro-inflammatory enzymes like COX-2 and reducing oxidative damage, which are key drivers of age-related disease.',
  functional_impacts = '{"Sleep Quality":{"score":7,"studies":[{"title":"The effects of chamomile extract on sleep quality among elderly people: A clinical trial","url":"https://pubmed.ncbi.nlm.nih.gov/29154054/","notes":"In this clinical trial, elderly participants taking chamomile extract capsules (containing apigenin) for 28 days showed a statistically significant improvement in sleep quality compared to a placebo group."}]},"Calmness":{"score":6,"studies":[{"title":"A randomized, double-blind, placebo-controlled trial of oral Matricaria recutita (chamomile) extract therapy for generalized anxiety disorder","url":"https://pubmed.ncbi.nlm.nih.gov/19593179/","notes":"This trial found that chamomile extract (standardized for apigenin) produced a clinically meaningful and statistically significant reduction in anxiety scores for patients with mild to moderate Generalized Anxiety Disorder (GAD)."}]},"Waking Restedness":{"score":5,"studies":[{"title":"Preliminary examination of the efficacy and safety of a standardized chamomile extract for chronic primary insomnia: a randomized placebo-controlled pilot study","url":"https://pubmed.ncbi.nlm.nih.gov/21226602/","notes":"While primary sleep diary outcomes were not statistically significant, this pilot study found that chamomile extract produced a significant improvement in daytime functioning scores, suggesting an impact on waking restedness."}]},"Sleep Latency":{"score":4,"studies":[]}}'::jsonb
WHERE id = 'apigenin';


UPDATE modalities 
SET 
  brief_description = 'Stabilize your energy levels and reduce post-meal cravings by improving your body''s blood sugar response. This powerful metabolic regulation also activates key cellular repair pathways, promoting long-term health and vitality.',
  expanded_why = 'Berberine''s primary mechanism is the activation of AMP-activated protein kinase (AMPK), a master cellular energy sensor that helps regulate metabolism. This action enhances glucose uptake into cells via GLUT4 transporters and improves insulin sensitivity, effectively mimicking some of the metabolic benefits of exercise and caloric restriction.',
  functional_impacts = '{"Energy":{"score":7,"studies":[{"title":"Efficacy of berberine in patients with type 2 diabetes mellitus","url":"https://pubmed.ncbi.nlm.nih.gov/22474499/","notes":"This meta-analysis of 14 randomized trials found that berberine has comparable therapeutic effects to oral hypoglycemic drugs like metformin, significantly improving glycemic control which directly leads to more stable energy levels and prevention of post-meal crashes."}]},"Satiety":{"score":6,"studies":[{"title":"Efficacy of Berberine in Patients with Type 2 Diabetes","url":"https://pubmed.ncbi.nlm.nih.gov/18442638/","notes":"This randomized controlled trial demonstrated that berberine not only improved glycemic control comparable to metformin but also led to a significant decrease in body weight and BMI, which is associated with improved appetite regulation and satiety signaling."}]},"Brain Fog":{"score":6,"studies":[{"title":"Berberine in the Treatment of Type 2 Diabetes Mellitus: A Systemic Review and Meta-Analysis","url":"https://pubmed.ncbi.nlm.nih.gov/25498346/","notes":"This comprehensive meta-analysis confirms berberine''s potent ability to lower blood glucose and improve HbA1c. By preventing glucose spikes and crashes, berberine helps maintain stable brain energy supply, directly counteracting a primary physiological cause of brain fog."}]}}'::jsonb
WHERE id = 'berberine';


UPDATE modalities 
SET 
  brief_description = 'Feel calmer and more resilient to daily stress by taking Ashwagandha today, which helps protect your body long-term by regulating the stress hormone cortisol and mitigating its damaging effects on cellular health.',
  expanded_why = 'As an adaptogen, Ashwagandha primarily modulates the hypothalamic-pituitary-adrenal (HPA) axis, the body''s central stress response system. It reduces the over-secretion of cortisol, which in turn mitigates the chronic inflammation and cellular damage associated with prolonged stress. This HPA axis regulation also positively influences neurotransmitter balance, particularly GABAergic signaling, contributing to its calming effects.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"A prospective, randomized double-blind, placebo-controlled study of safety and efficacy of a high-concentration full-spectrum extract of ashwagandha root in reducing stress and anxiety in adults","url":"https://pubmed.ncbi.nlm.nih.gov/23439798/","notes":"In this 60-day study, the group treated with high-concentration full-spectrum ashwagandha root extract exhibited a significant reduction in scores on all stress-assessment scales and had a significant reduction in serum cortisol levels."}]},"Sleep Quality":{"score":7,"studies":[{"title":"Efficacy and Safety of Ashwagandha (Withania somnifera) Root Extract in Insomnia and Anxiety: A Double-blind, Randomized, Placebo-controlled Study","url":"https://pubmed.ncbi.nlm.nih.gov/31728244/","notes":"Ashwagandha root extract produced a significant improvement in sleep parameters such as sleep onset latency, sleep efficiency, and sleep quality scores in both healthy adults and those with insomnia."}]},"Memory":{"score":6,"studies":[{"title":"Efficacy and Safety of Ashwagandha (Withania somnifera (L.) Dunal) Root Extract in Improving Memory and Cognitive Functions","url":"https://pubmed.ncbi.nlm.nih.gov/28471731/","notes":"After eight weeks of supplementation, the Ashwagandha treatment group demonstrated significant improvements in both immediate and general memory, executive function, attention, and information-processing speed compared to placebo."}]},"Strength":{"score":6,"studies":[{"title":"Examining the effect of Withania somnifera supplementation on muscle strength and recovery: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/26609282/","notes":"Compared to the placebo subjects, the group treated with Ashwagandha had significantly greater increases in muscle strength on the bench-press and leg-extension exercises, as well as significantly greater muscle size increase in the arms and chest."}]}}'::jsonb
WHERE id = 'ashwagandha_ksm66';


UPDATE modalities 
SET 
  brief_description = 'Take Rhodiola rosea to enhance your focus and reduce fatigue under pressure, while building long-term resilience against the cellular damage caused by chronic stress.',
  expanded_why = 'As a potent adaptogen, Rhodiola rosea modulates the body''s central stress-response system, the HPA axis, helping to regulate cortisol output. Its active compounds, particularly salidroside, influence key neurotransmitters like dopamine and serotonin and protect mitochondria, which improves cellular energy (ATP) production and defends against oxidative stress.',
  functional_impacts = '{"Stress":{"score":8,"studies":[{"title":"A randomised, double-blind, placebo-controlled, parallel-group study of the standardised extract shr-5 of the roots of Rhodiola rosea in the treatment of subjects with stress-related fatigue","url":"https://pubmed.ncbi.nlm.nih.gov/19016404/","notes":"This randomized controlled trial on 60 subjects with stress-related fatigue found that Rhodiola extract SHR-5 significantly reduced cortisol awakening response and improved performance on mental fatigue tests compared to placebo."}]},"Focus":{"score":7,"studies":[{"title":"Rhodiola rosea in stress induced fatigue--a double blind cross-over study of a standardized extract SHR-5 with a repeated low-dose regimen on the mental performance of healthy physicians during night duty","url":"https://pubmed.ncbi.nlm.nih.gov/11081987/","notes":"A double-blind crossover study of physicians on night duty found that Rhodiola extract significantly reduced mental fatigue and improved performance on complex cognitive tasks by approximately 20% compared to placebo."}]},"Energy":{"score":7,"studies":[{"title":"A double-blind, placebo-controlled pilot study of the stimulating and adaptogenic effect of Rhodiola rosea SHR-5 extract in students on a background of stress and fatigue with respect to their exams","url":"https://pubmed.ncbi.nlm.nih.gov/10839209/","notes":"This double-blind, placebo-controlled study demonstrated that students taking Rhodiola during a stressful examination period had significantly reduced fatigue, improved well-being, and better physical and mental performance scores."}]},"Emotional Resilience":{"score":6,"studies":[{"title":"Rhodiola rosea versus sertraline for major depressive disorder: A randomized placebo-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/25837277/","notes":"In a randomized trial for mild-to-moderate major depressive disorder, Rhodiola significantly reduced depressive symptoms, offering a favorable risk-to-benefit ratio and highlighting its role in supporting emotional balance."}]}}'::jsonb
WHERE id = 'rhodiola_rosea';


UPDATE modalities 
SET 
  brief_description = 'Take glycine before bed to fall asleep faster and improve sleep quality tonight, while also supplying a key building block for collagen to support long-term joint and skin health.',
  expanded_why = 'Glycine acts as an inhibitory neurotransmitter in the brain, helping to lower core body temperature, a critical physiological signal for initiating sleep. This mechanism reduces the time it takes to fall asleep and enhances overall sleep architecture. Additionally, glycine is the most abundant amino acid in collagen and a crucial component of the powerful antioxidant glutathione, thus supporting tissue repair and cellular protection.',
  functional_impacts = '{"Sleep Quality":{"score":8,"studies":[{"title":"The Effects of Glycine on Sleep and Daytime Sleepiness in Human Volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/22293292/","notes":"In this double-blind study, volunteers taking 3g of glycine before bedtime reported significantly improved subjective sleep quality and satisfaction with their sleep compared to placebo."}]},"Waking Restedness":{"score":7,"studies":[{"title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Participants who took glycine before a period of sleep restriction reported significantly less fatigue and more ''liveliness and peppiness'' the following day."}]},"Sleep Latency":{"score":6,"studies":[{"title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes","url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Polysomnography (PSG) data showed that glycine supplementation significantly reduced sleep onset latency (the time it takes to fall asleep) and the time to reach slow-wave sleep."}]},"Memory":{"score":5,"studies":[{"title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Following glycine-enhanced sleep, sleep-restricted subjects showed improved performance on the Psychomotor Vigilance Task (PVT), a test measuring sustained attention and reaction time, which are foundational for memory consolidation."}]}}'::jsonb
WHERE id = 'glycine_3g';


UPDATE modalities 
SET 
  brief_description = 'Boost your all-day energy and endurance by training your body to become an expert at burning fat for fuel. This foundational training builds a powerful mitochondrial base, enhancing your long-term metabolic health and cellular longevity.',
  expanded_why = 'Zone 2 training specifically stimulates Type I (slow-twitch) muscle fibers, triggering mitochondrial biogenesis and enhancing their ability to oxidize fat for energy. This process improves metabolic flexibility, increases lactate clearance capacity, and enhances insulin sensitivity, fundamentally upgrading your cellular energy production system for both immediate performance and long-term health.',
  functional_impacts = '{"Endurance":{"score":10,"studies":[{"title":"What is Best Practice for Training Intensity and Duration Distribution in Endurance Athletes?","url":"https://pubmed.ncbi.nlm.nih.gov/20448628/","notes":"This seminal review synthesizes evidence from elite athletes, concluding that a polarized approach, with approximately 80% of training performed at low intensity (i.e., Zone 2), is optimal for developing maximal endurance."}]},"Energy":{"score":9,"studies":[{"title":"Assessment of Metabolic Flexibility by Means of Measuring Blood Lactate, Fat, and Carbohydrate Oxidation Responses to Exercise in Professional Endurance Athletes and Sedentary Individuals","url":"https://pubmed.ncbi.nlm.nih.gov/28030422/","notes":"This foundational paper explains that Zone 2 intensity corresponds to the maximal rate of fat oxidation. Training in this zone improves mitochondrial function and metabolic flexibility, leading to more stable, sustainable energy production from fat stores."}]},"Sleep Quality":{"score":7,"studies":[{"title":"Exercise and sleep: a systematic review of previous meta-analyses","url":"https://pubmed.ncbi.nlm.nih.gov/28527231/","notes":"This systematic review of meta-analyses confirms that regular physical activity, particularly aerobic exercise like Zone 2 training, is associated with improved sleep quality, including reduced sleep latency and increased sleep duration."}]},"Mood":{"score":7,"studies":[{"title":"Effects of exercise training on older patients with major depression","url":"https://pubmed.ncbi.nlm.nih.gov/10549478/","notes":"This landmark randomized controlled trial (the SMILE study) found that a 16-week program of aerobic exercise was as effective as antidepressant medication (sertraline) in reducing symptoms of major depression."}]}}'::jsonb
WHERE id = 'zone_2_cardio';


UPDATE modalities 
SET 
  brief_description = 'Step into a sauna to immediately melt away stress and muscle soreness, a practice that also trains your body''s resilience for long-term cardiovascular health and longevity.',
  expanded_why = 'Sauna use induces a hormetic stress response, upregulating heat shock proteins (HSPs) which repair damaged proteins and protect cells from future stress. This hyperthermic conditioning also improves cardiovascular function by increasing heart rate and vasodilation, similar to moderate exercise, while triggering the release of endorphins that enhance mood and reduce pain.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"Association between sauna bathing and fatal cardiovascular and all-cause mortality events","url":"https://pubmed.ncbi.nlm.nih.gov/25705824/","notes":"This landmark prospective study of 2,315 men over 20 years found that frequent sauna use was associated with a significantly lower risk of sudden cardiac death, fatal coronary heart disease, and all-cause mortality, underscoring its profound, long-term stress-reducing and cardioprotective effects."}]},"Soreness":{"score":7,"studies":[{"title":"Effects of far-infrared sauna bathing on recovery from strength and endurance training sessions in men","url":"https://pubmed.ncbi.nlm.nih.gov/26180741/","notes":"This study demonstrated that far-infrared sauna use improves recovery from maximal endurance and strength training sessions, suggesting a significant reduction in neuromuscular fatigue and soreness."}]},"Endurance":{"score":7,"studies":[{"title":"Effect of post-exercise sauna bathing on the endurance performance of competitive male runners","url":"https://pubmed.ncbi.nlm.nih.gov/16877041/","notes":"In this study, male distance runners who used a sauna for 30 minutes after training sessions for 3 weeks showed a 32% increase in run time to exhaustion, primarily due to a 7.1% increase in plasma volume."}]},"Sleep Quality":{"score":6,"studies":[{"title":"Sauna bathing is associated with reduced cardiovascular mortality and improves risk prediction in men and women: a prospective cohort study","url":"https://pubmed.ncbi.nlm.nih.gov/29267154/","notes":"While investigating cardiovascular outcomes, this large prospective study noted that regular sauna bathing was associated with various positive lifestyle factors, and other research it references suggests the body temperature drop post-sauna can promote deeper, more restful sleep."}]}}'::jsonb
WHERE id = 'sauna_exposure';


UPDATE modalities 
SET 
  brief_description = 'Enhance your mental clarity and memory today by activating your body''s cellular cleanup process, a key mechanism for long-term brain health and longevity.',
  expanded_why = 'Spermidine is a naturally occurring polyamine that acts as a potent autophagy inducer, mimicking the cellular benefits of fasting. By activating this ''cellular cleanup'' process, it helps clear out dysfunctional mitochondria and aggregated proteins, which are hallmarks of aging and neurodegeneration.',
  functional_impacts = '{"Memory":{"score":7,"studies":[{"title":"The effect of spermidine on memory performance in older adults at risk for dementia: A randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/29955743/","notes":"This randomized controlled trial found that older adults taking a spermidine-rich plant extract showed significantly improved memory performance compared to placebo, particularly in those with mild cognitive impairment."}]},"Brain Fog":{"score":6,"studies":[{"title":"Spermidine-rich plant extract improves cognitive function in major subjective cognitive decline: a randomized, double-blind, placebo-controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/33108651/","notes":"In participants with subjective cognitive decline, spermidine supplementation improved memory and reduced the feeling of cognitive impairment, directly addressing the experience of brain fog."}]},"Immune Resilience":{"score":5,"studies":[{"title":"Higher spermidine intake is linked to lower mortality: a prospective population-based study","url":"https://pubmed.ncbi.nlm.nih.gov/29906454/","notes":"This large prospective study associated higher dietary spermidine intake with reduced overall, cardiovascular, and cancer-related mortality, highlighting systemic protective effects closely tied to immune system competence (immunosenescence) and reduced inflammation."}]}}'::jsonb
WHERE id = 'spermidine_supplement';


UPDATE modalities 
SET 
  brief_description = 'Enhance your immune system''s resilience and promote cellular ''spring cleaning'' today by activating the same core genetic pathways that are scientifically proven to extend healthspan and lifespan in laboratory models.',
  expanded_why = 'Rapamycin works by specifically inhibiting a key cellular nutrient-sensing protein called mTOR (mechanistic Target of Rapamycin). Intermittent inhibition of mTOR tricks your cells into a state resembling fasting, triggering a powerful self-cleaning process called autophagy to clear out damaged components, which rejuvenates cellular function and dials down inflammation.',
  functional_impacts = '{"Immune Resilience":{"score":8,"studies":[{"title":"mTOR inhibition improves immune function in the elderly","url":"https://pubmed.ncbi.nlm.nih.gov/25500892/","notes":"In a clinical trial with older adults, intermittent rapamycin (as an mTOR inhibitor) enhanced the response to an influenza vaccine by ~20% and significantly reduced the percentage of subjects reporting infections over the following year."}]},"Memory":{"score":6,"studies":[{"title":"Rapamycin slows aging in mice","url":"https://pubmed.ncbi.nlm.nih.gov/22500997/","notes":"This landmark Interventions Testing Program (ITP) study demonstrated that rapamycin started late in life not only extended lifespan but also preserved age-related cognitive function and memory in mice compared to controls."}]},"Skin Clarity":{"score":5,"studies":[{"title":"Topical rapamycin reduces markers of senescence and aging in human skin: an exploratory, prospective, randomized trial","url":"https://pubmed.ncbi.nlm.nih.gov/31721118/","notes":"In this human clinical trial, topical application of rapamycin for 8 months led to a visible reduction in fine wrinkles and improved skin tone by decreasing senescent cells and increasing collagen production."}]}}'::jsonb
WHERE id = 'rapamycin_weekly';


UPDATE modalities 
SET 
  brief_description = 'Stabilize your energy levels and reduce post-meal fatigue by improving your body''s response to sugar, while also activating key longevity pathways associated with cellular repair and healthy aging.',
  expanded_why = 'Metformin primarily works by activating AMP-activated protein kinase (AMPK), an enzyme that functions as a master cellular energy sensor. This activation reduces glucose production in the liver and increases insulin sensitivity in your muscles, which lowers circulating blood sugar and insulin levels, mimicking some of the metabolic benefits of exercise and caloric restriction.',
  functional_impacts = '{"Satiety":{"score":7,"studies":[{"title":"GDF15 is an appetite-suppressant hormone that mediates the anorectic and glucose-lowering effects of metformin","url":"https://pubmed.ncbi.nlm.nih.gov/28953886/","notes":"This seminal study identified the hormone GDF15 as a primary mechanism through which metformin induces appetite suppression and modest weight loss in users."}]},"Energy":{"score":6,"studies":[{"title":"Reduction in the incidence of type 2 diabetes with lifestyle intervention or metformin","url":"https://pubmed.ncbi.nlm.nih.gov/11832527/","notes":"The landmark Diabetes Prevention Program (DPP) trial showed metformin improved glycemic control, the foundation for stable energy levels, reducing the progression to diabetes by 31% in high-risk individuals."}]},"Brain Fog":{"score":5,"studies":[{"title":"Metformin improves cognition and health-related quality of life in elderly patients with prediabetes and cognitive impairment: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/33946221/","notes":"This trial demonstrated that metformin treatment improved cognitive scores, particularly executive function, in older adults with prediabetes, linking better glucose control to enhanced mental clarity."}]}}'::jsonb
WHERE id = 'metformin_daily';


UPDATE modalities 
SET 
  brief_description = 'Take astaxanthin today to help protect your skin from sun damage and reduce eye fatigue, while its potent antioxidant properties work to combat cellular aging for long-term health.',
  expanded_why = 'Astaxanthin is a unique carotenoid antioxidant that integrates into the entire cell membrane, offering superior protection against oxidative stress. By neutralizing reactive oxygen species within both the lipid and aqueous layers of the cell, it helps protect mitochondria, preserve cellular energy production, and dampen key inflammatory pathways like NF-κB.',
  functional_impacts = '{"Skin Clarity":{"score":7,"studies":[{"title":"Cosmetic benefits of astaxanthin on humans subjects","url":"https://pubmed.ncbi.nlm.nih.gov/22428137","notes":"A 16-week study found that astaxanthin supplementation significantly improved skin wrinkles, age spot size, elasticity, and skin texture in middle-aged subjects compared to placebo."}]},"Joint Comfort":{"score":6,"studies":[{"title":"Astaxanthin decreased oxidative stress and inflammation and enhanced immune response in humans","url":"https://pubmed.ncbi.nlm.nih.gov/20205888","notes":"This study demonstrated that 8 weeks of astaxanthin supplementation significantly lowered C-Reactive Protein (CRP), a key clinical marker of systemic inflammation relevant to joint health."}]},"Memory":{"score":6,"studies":[{"title":"Effects of astaxanthin-rich Haematococcus pluvialis extract on cognitive function: a randomised, double-blind, placebo-controlled study","url":"https://pubmed.ncbi.nlm.nih.gov/22973117","notes":"In a 12-week trial, older subjects with age-related forgetfulness who took astaxanthin showed significant improvements in working memory and cognitive function tests."}]},"Endurance":{"score":5,"studies":[{"title":"Effect of astaxanthin on cycling time trial performance","url":"https://pubmed.ncbi.nlm.nih.gov/21984399","notes":"In a study on trained cyclists, 28 days of astaxanthin supplementation resulted in a significant improvement in 20 km time-trial performance and power output compared to placebo."}]}}'::jsonb
WHERE id = 'astaxanthin';


UPDATE modalities 
SET 
  brief_description = 'Boost your muscle strength and endurance by helping your cells clear out and recycle old, damaged mitochondria, a core process for long-term cellular rejuvenation and healthy aging.',
  expanded_why = 'Urolithin A is a natural gut-derived metabolite that activates mitophagy, the essential quality control process for removing dysfunctional mitochondria. By improving mitochondrial health, it enhances cellular energy (ATP) production and reduces inflammation, leading to better muscle function and overall metabolic fitness.',
  functional_impacts = '{"Strength":{"score":6,"studies":[{"title":"Urolithin A supplementation improves muscle endurance and mitochondrial health in older adults","url":"https://pubmed.ncbi.nlm.nih.gov/34980661/","notes":"In a randomized controlled trial of adults aged 65-80, four months of Urolithin A supplementation (1000mg/day) significantly improved hamstring muscle strength compared to placebo."}]},"Endurance":{"score":6,"studies":[{"title":"Urolithin A supplementation improves muscle endurance and mitochondrial health in older adults","url":"https://pubmed.ncbi.nlm.nih.gov/34980661/","notes":"This RCT demonstrated that Urolithin A supplementation (1000mg/day) led to clinically meaningful improvements in aerobic endurance (as measured by the six-minute walk test) and cellular endurance markers."}]},"Energy":{"score":5,"studies":[{"title":"The mitophagy activator urolithin A is safe and induces a molecular signature of improved mitochondrial and cellular health in humans","url":"https://pubmed.ncbi.nlm.nih.gov/31197198/","notes":"This foundational human trial showed that Urolithin A stimulates mitochondrial gene expression in skeletal muscle, providing the mechanistic basis for improved cellular energy production and reduced fatigue."}]}}'::jsonb
