UPDATE modalities 
SET 
  brief_description = 'Melatonin helps you fall asleep faster and enjoy higher quality sleep tonight. This foundational sleep improvement also supports long-term health by acting as a powerful antioxidant that protects your mitochondria and cells from age-related damage.',
  expanded_why = 'Melatonin is the primary hormone that regulates the body''s circadian rhythm, signaling darkness to the brain to initiate sleep via MT1 and MT2 receptor activation in the suprachiasmatic nucleus. Beyond its chronobiotic role, it is a potent, direct free radical scavenger and stimulates the production of endogenous antioxidant enzymes, thereby protecting mitochondria and DNA from oxidative stress, a key driver of aging.',
  functional_impacts = '{"Sleep Quality":{"score":9,"studies":[{"title":"Meta-analysis: melatonin for the treatment of primary sleep disorders","url":"https://pubmed.ncbi.nlm.nih.gov/23691095/","notes":"This meta-analysis of 19 randomized controlled trials found that melatonin administration significantly improved overall sleep quality, increased total sleep time, and reduced the time it took to fall asleep."}]},"Sleep Latency":{"score":8,"studies":[{"title":"Meta-analysis: melatonin for the treatment of primary sleep disorders","url":"https://pubmed.ncbi.nlm.nih.gov/23691095/","notes":"The same meta-analysis demonstrated that subjects taking melatonin fell asleep significantly faster, reducing sleep onset latency by an average of 7.06 minutes compared to placebo."}]},"Waking Restedness":{"score":7,"studies":[{"title":"Efficacy of prolonged-release melatonin in insomnia patients aged 55-80 years: quality of sleep and next-day alertness outcomes","url":"https://pubmed.ncbi.nlm.nih.gov/17875249/","notes":"This randomized controlled trial found that prolonged-release melatonin significantly improved not only sleep quality but also morning alertness and health-related quality of life compared to placebo, without causing withdrawal symptoms upon discontinuation."}]}}'::jsonb
WHERE id = 'melatonin';


UPDATE modalities 
SET 
  brief_description = 'See exactly how your diet and lifestyle affect your metabolic state in real-time to achieve stable energy and mental clarity, which over time supports cellular cleanup and long-term metabolic health.',
  expanded_why = 'Continuous Ketone Monitors measure your primary circulating ketone body, beta-hydroxybutyrate (BHB), providing instant feedback on your body''s transition to using fat for fuel. Sustaining this state of ketosis activates key longevity pathways like AMPK and sirtuins, which promotes autophagy and mitochondrial health, while also reducing inflammation by inhibiting the NLRP3 inflammasome.',
  functional_impacts = '{"Satiety":{"score":9,"studies":[{"title":"Do ketogenic diets really suppress appetite? A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/25402637/","notes":"This meta-analysis of 13 studies confirmed that individuals on very-low-carbohydrate ketogenic diets consistently report significantly lower levels of hunger and a reduced desire to eat compared to those on other diets."}]},"Focus":{"score":8,"studies":[{"title":"Dietary ketosis enhances memory in mild cognitive impairment","url":"https://pubmed.ncbi.nlm.nih.gov/21130529/","notes":"In older adults with mild cognitive impairment, a high-fat ketogenic diet for 6 weeks led to significant improvements in verbal memory performance, which was directly correlated with the level of circulating ketones."}]},"Energy":{"score":8,"studies":[{"title":"The effects of a 6-week ketogenic diet on CrossFit-style workouts","url":"https://pubmed.ncbi.nlm.nih.gov/30206531/","notes":"Athletes following a 6-week ketogenic diet showed no decrement in high-intensity exercise performance and maintained workout intensity, indicating ketones provide a stable and sufficient energy source for demanding physical activity."}]},"Mood":{"score":6,"studies":[{"title":"The Ketogenic Diet for Refractory Mental Illness: A Retrospective Analysis of 31 Inpatients","url":"https://pubmed.ncbi.nlm.nih.gov/38624933/","notes":"A retrospective analysis of inpatients with severe, treatment-resistant mental illness found that a ketogenic diet was associated with significant improvements in psychiatrist-rated depression and psychosis scores, as well as self-reported overall well-being."}]}}'::jsonb
WHERE id = 'continuous_ketone_monitors';


UPDATE modalities 
SET 
  brief_description = 'Maintain a consistent sleep schedule to boost your focus and energy for today, which reinforces your body''s internal clock for long-term metabolic health and cellular repair.',
  expanded_why = 'Going to bed and waking up at the same time each day, even on weekends, anchors your master circadian clock in the brain''s suprachiasmatic nucleus (SCN). This stable rhythm orchestrates the timely release of hormones like cortisol and melatonin, optimizing everything from glucose metabolism to the nightly cellular cleanup process known as autophagy, which is critical for clearing damaged components and preventing age-related diseases.',
  functional_impacts = '{"Waking Restedness":{"score":9,"studies":[{"title":"The impact of sleep timing and regularity on elite athletic performance","url":"https://pubmed.ncbi.nlm.nih.gov/34297928/","notes":"This study in elite athletes found that irregular sleep timing, independent of duration, was associated with higher levels of daytime sleepiness and poorer performance, highlighting the critical role of consistency in feeling rested."}]},"Focus":{"score":8,"studies":[{"title":"Irregular sleep/wake patterns are associated with poorer academic performance and delayed circadian and sleep/wake timing","url":"https://pubmed.ncbi.nlm.nih.gov/28607475/","notes":"This study of college students demonstrated that individuals with more irregular sleep patterns had poorer academic performance, a direct proxy for cognitive functions like focus and attention."}]},"Mood":{"score":8,"studies":[{"title":"Sleep regularity is a stronger predictor of depression than sleep duration in a sample of university students","url":"https://pubmed.ncbi.nlm.nih.gov/32019927/","notes":"Researchers found that sleep regularity was more strongly associated with mood and risk of depression than total sleep time, suggesting schedule consistency is a key factor for emotional well-being."}]},"Immune Resilience":{"score":7,"studies":[{"title":"Adverse metabolic and cardiovascular consequences of circadian misalignment","url":"https://pubmed.ncbi.nlm.nih.gov/19901158/","notes":"This highly-controlled laboratory study showed that misaligning the circadian clock (a direct result of inconsistent sleep) increased inflammatory markers like C-reactive protein (CRP) and insulin resistance, indicating a state of immune and metabolic stress."}]}}'::jsonb
WHERE id = 'sleep_consistency';


UPDATE modalities 
SET 
  brief_description = 'Take quercetin to reduce allergy symptoms and inflammation for clearer breathing and greater comfort today, while it works long-term to clear out aging cells and protect against oxidative stress.',
  expanded_why = 'Quercetin is a powerful flavonoid that acts as an antioxidant and anti-inflammatory by inhibiting enzymes like COX and LOX and stabilizing mast cells to reduce histamine release. On a cellular level, it promotes longevity by acting as a senolytic, helping to induce apoptosis (programmed cell death) in senescent ''zombie'' cells that contribute to aging and disease.',
  functional_impacts = '{"Immune Resilience":{"score":7,"studies":[{"title":"Quercetin reduces illness, oxidative stress and inflammation in elite athletes","url":"https://pubmed.ncbi.nlm.nih.gov/17805089/","notes":"A 3-week trial with cyclists showed that 1000mg/day of quercetin supplementation resulted in a significantly lower incidence of upper respiratory tract infections following intense exercise compared to placebo."}]},"Joint Comfort":{"score":6,"studies":[{"title":"The Effect of Quercetin on Inflammatory Factors and Clinical Symptoms in Women with Rheumatoid Arthritis: A Double-Blind, Randomized Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/27710596/","notes":"In women with rheumatoid arthritis, 8 weeks of quercetin supplementation (500mg/day) significantly improved morning stiffness, morning pain, and after-activity pain compared to placebo."}]},"Soreness":{"score":6,"studies":[{"title":"The effects of quercetin supplementation on eccentric exercise-induced muscle damage","url":"https://pubmed.ncbi.nlm.nih.gov/31035613/","notes":"Supplementation with quercetin for 14 days attenuated the loss of muscle strength and reduced markers of muscle damage (like Myoglobin) following eccentric exercise in healthy young men."}]}}'::jsonb
WHERE id = 'quercetin';


UPDATE modalities 
SET 
  brief_description = 'Gain invaluable peace of mind today with a comprehensive, radiation-free snapshot of your internal health, enabling the earliest possible detection of cancer and other diseases to dramatically improve long-term outcomes.',
  expanded_why = 'Whole-body MRI (WB-MRI) utilizes powerful magnetic fields and radio waves to create detailed images of your soft tissues, organs, and bones. This non-invasive screening excels at detecting abnormalities like solid tumors, inflammation, and vascular issues in their nascent stages, often before clinical symptoms manifest. This early detection allows for proactive intervention, which is critical for extending healthspan and improving treatment success rates.',
  functional_impacts = '{"Calmness":{"score":8,"studies":[{"title":"Whole-body magnetic resonance imaging in asymptomatic subjects: a means to re-assure the ''worried well'' or a source of new anxiety?","url":"https://pubmed.ncbi.nlm.nih.gov/16787968","notes":"In a study of 45 asymptomatic individuals, the majority reported a reassuring effect and reduced health-related anxiety after receiving normal whole-body MRI results."}]},"Stress":{"score":8,"studies":[{"title":"Benefits and harms of whole-body MRI screening in asymptomatic persons: a systematic review","url":"https://pubmed.ncbi.nlm.nih.gov/33459740","notes":"This systematic review of 12 studies found that most reported a reassuring effect and a decrease in anxiety (a key marker of stress) after a normal WB-MRI result."}]},"Motivation":{"score":6,"studies":[{"title":"Whole-body MRI for preventative screening: a multicenter study on patient-reported outcomes and experiences","url":"https://pubmed.ncbi.nlm.nih.gov/36290885","notes":"In a large survey of 1528 participants who underwent preventative WB-MRI, 78.3% reported making at least one positive lifestyle change afterwards."}]}}'::jsonb
WHERE id = 'whole_body_mri';


UPDATE modalities 
SET 
  brief_description = 'Gain powerful, data-driven motivation to upgrade your health habits by discovering your body''s true internal age, allowing you to track the real-world impact of your lifestyle choices.',
  expanded_why = 'Biological age tests analyze a variety of biomarkers, most commonly DNA methylation patterns (epigenetic clocks), to assess the cumulative impact of your lifestyle and environment on your cellular health. This provides a more accurate and actionable measure of your aging trajectory than your chronological age, offering a quantifiable target for interventions designed to improve healthspan.',
  functional_impacts = '{"Motivation":{"score":8,"studies":[{"title":"Effect of Personalized Nutrition on Health-Related Behaviour Change: A Systematic Review With Meta-Analysis","url":"https://pubmed.ncbi.nlm.nih.gov/32230752/","notes":"This meta-analysis of 11 randomized controlled trials found that providing individuals with personalized health information results in significantly greater and more sustained positive changes in health behaviors compared to generic advice."}]},"Focus":{"score":6,"studies":[{"title":"A review of the impact of personalizing nutrition on health-related attitudes and behavior","url":"https://pubmed.ncbi.nlm.nih.gov/30128522/","notes":"This review concludes that personalized feedback can enhance engagement and focus by helping individuals understand their personal health risks, thereby leading to more targeted and effective lifestyle modifications."}]}}'::jsonb
WHERE id = 'biological_age_testing';


UPDATE modalities 
SET 
  brief_description = 'Enhance your daily energy and mental clarity by revitalizing your cellular powerhouses, a process fundamental for promoting long-term health and vitality.',
  expanded_why = 'Shilajit''s primary active component, fulvic acid, improves mitochondrial function by facilitating the transport of key minerals and nutrients into the cell, boosting ATP energy production. Simultaneously, its rich antioxidant profile, including dibenzo-α-pyrones, protects these cellular power plants from oxidative stress, supporting overall resilience and cognitive health.',
  functional_impacts = '{"Strength":{"score":8,"studies":[{"title":"The effects of Shilajit supplementation on fatigue-induced decreases in muscular strength and serum hydroxyproline levels","url":"https://pubmed.ncbi.nlm.nih.gov/30729223/","notes":"In this RCT, 8 weeks of supplementation with 500 mg/d of Shilajit preserved maximal muscular strength following a fatiguing protocol and reduced markers of connective tissue breakdown compared to placebo."}]},"Energy":{"score":7,"studies":[{"title":"The Human Skeletal Muscle Transcriptome in Response to Oral Shilajit Supplementation","url":"https://pubmed.ncbi.nlm.nih.gov/27414521/","notes":"This study showed that Shilajit supplementation in overweight adults promoted skeletal muscle adaptation through the upregulation of genes associated with extracellular matrix health, nutrient transport, and endothelial function, which are foundational for energy metabolism."}]},"Libido":{"score":7,"studies":[{"title":"Clinical evaluation of purified Shilajit on testosterone levels in healthy volunteers","url":"https://pubmed.ncbi.nlm.nih.gov/26395129/","notes":"In this placebo-controlled study, 90 days of supplementation with 250 mg of Shilajit twice daily significantly increased total testosterone, free testosterone, and dehydroepiandrosterone (DHEAS) in healthy men aged 45-55."}]},"Memory":{"score":6,"studies":[{"title":"Shilajit: a natural phytocomplex with potential procognitive activity","url":"https://pubmed.ncbi.nlm.nih.gov/22482077/","notes":"This review outlines the neuroprotective mechanism of Shilajit''s fulvic acid component, which has been shown in vitro to inhibit the aggregation and promote the disassembly of tau protein, a key factor in cognitive decline."}]}}'::jsonb
WHERE id = 'shilajit';


UPDATE modalities 
SET 
  brief_description = 'Build muscle and strength with significantly lighter weights to reduce joint stress today, while preserving metabolically critical muscle mass for a longer, healthier lifespan.',
  expanded_why = 'BFR training involves restricting venous blood flow from a limb during light exercise, creating a localized low-oxygen environment. This metabolic stress mimics high-intensity training, triggering a potent anabolic response that recruits fast-twitch muscle fibers and increases growth factors to build muscle without the need for heavy, joint-damaging loads.',
  functional_impacts = '{"Strength":{"score":8,"studies":[{"title":"Blood flow restriction training in clinical musculoskeletal rehabilitation: a systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/28497523/","notes":"This meta-analysis of 20 studies concluded that low-load BFR training is more effective than low-load training alone and as effective as traditional high-load training for increasing muscle strength."}]},"Joint Comfort":{"score":7,"studies":[{"title":"The Effects of Blood Flow Restriction Training in the Treatment of Knee Osteoarthritis: A Systematic Review and Meta-Analysis","url":"https://pubmed.ncbi.nlm.nih.gov/32488941/","notes":"This review found that low-load BFR training significantly improved pain, physical function, and muscle strength in patients with knee osteoarthritis, providing an effective exercise option with minimal joint stress."}]},"Endurance":{"score":6,"studies":[{"title":"Effects of low-intensity cycle training with restricted leg blood flow on thigh muscle volume and VO2max in young men","url":"https://pubmed.ncbi.nlm.nih.gov/15705727/","notes":"This study showed that low-intensity cycle training with BFR significantly increased not only muscle size and strength but also maximal oxygen uptake (VO2max), a key marker of aerobic endurance."}]}}'::jsonb
WHERE id = 'bfr_training';


UPDATE modalities 
SET 
  brief_description = 'Boost your cellular energy production today for improved physical vitality, while also providing your mitochondria with powerful antioxidant protection against long-term oxidative damage, a key driver of aging.',
  expanded_why = 'Coenzyme Q10 is an essential component of the mitochondrial electron transport chain, acting as an electron carrier to facilitate the creation of ATP, the fundamental energy molecule for all cellular processes. Beyond its role in energy metabolism, CoQ10 in its reduced form (ubiquinol) is a potent lipid-soluble antioxidant, neutralizing free radicals and protecting cellular membranes, DNA, and proteins from oxidative stress.',
  functional_impacts = '{"Energy":{"score":8,"studies":[{"title":"The effect of coenzyme Q10 supplementation on fatigue: A systematic review and meta-analysis of interventional studies","url":"https://pubmed.ncbi.nlm.nih.gov/36728514/","notes":"This 2023 meta-analysis of 17 randomized controlled trials found that CoQ10 supplementation significantly improved fatigue scores compared to placebo, particularly in individuals with conditions associated with fatigue."}]},"Endurance":{"score":6,"studies":[{"title":"Effects of coenzyme Q10 supplementation on exercise performance in trained athletes","url":"https://pubmed.ncbi.nlm.nih.gov/18413341/","notes":"In this double-blind, placebo-controlled study, trained athletes supplementing with CoQ10 showed a statistically significant increase in maximal power output and time to exhaustion during cycling exercises."}]},"Soreness":{"score":5,"studies":[{"title":"Coenzyme Q(10) supplementation ameliorates inflammatory signaling and oxidative stress associated with strenuous exercise","url":"https://pubmed.ncbi.nlm.nih.gov/22459704/","notes":"This study on professional athletes found that CoQ10 supplementation reduced markers of muscle damage (creatine kinase) and inflammation (IL-6) following strenuous exercise, suggesting a protective effect that can mitigate soreness."}]},"Mood":{"score":5,"studies":[{"title":"Evaluating the Effect of Coenzyme Q10 Augmentation on Treatment of Bipolar Depression: A Double-Blind Controlled Clinical Trial","url":"https://pubmed.ncbi.nlm.nih.gov/30196522/","notes":"This clinical trial found that CoQ10, when used as an add-on therapy for patients with bipolar depression, resulted in a significant reduction in depression scores compared to placebo over 8 weeks."}]}}'::jsonb
WHERE id = 'coq10';
